window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-105"]=[{"id":"set2-v2csYT-J","fingerprint":"6ddef9f3eb3e9858","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele date anamnestice ale unui pacient edentat parțial influențează în mod direct etapizarea planului de tratament sau alegerea soluției terapeutice?","options":[{"id":"A","text":"Vârsta"},{"id":"B","text":"Sexul"},{"id":"C","text":"Domiciliul"},{"id":"D","text":"Profesia"},{"id":"E","text":"Motivele prezentării"}],"correct":["A","C","D"],"pages":[233],"source":"set-2"},{"id":"set2-voa1r8aC","fingerprint":"860de207229e26c3","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele reprezintă motive de prezentare ale pacientului cu edentație parțială întinsă?","options":[{"id":"A","text":"Leziuni ale mucoasei, alături de tulburări articulare și musculare."},{"id":"B","text":"Reoptimizarea unor restaurări protetice vechi, necorespunzătoare morfo-funcțional."},{"id":"C","text":"Dorința de a înlocui obturații vechi din amalgam cu materiale compozite."},{"id":"D","text":"Necesitatea unui control de rutină pentru profilaxie."},{"id":"E","text":"Tulburări funcționale masticatorii, fizionomice și fonetice."}],"correct":["A","B","E"],"pages":[234],"source":"set-2"},{"id":"set2-8alImfOW","fingerprint":"a106f5e866cd68f2","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt secțiunile componente ale anamnezei în cadrul examenului clinic al pacientului edentat parțial întins?","options":[{"id":"A","text":"Analiza statusului parodontal și a indicelui de placă."},{"id":"B","text":"Istoricul afecțiunii."},{"id":"C","text":"Antecedentele heredocolaterale și personale."},{"id":"D","text":"Antecedentele generale (APG) și stomatologice (APS)."},{"id":"E","text":"Evaluarea modelelor de studiu și a examenelor radiologice."}],"correct":["B","C","D"],"pages":[234],"source":"set-2"},{"id":"set2-HLqoDCmj","fingerprint":"911df3c9761bba6d","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce informații relevante pentru planul de tratament se pot obține din istoricul afecțiunii unui pacient edentat?","options":[{"id":"A","text":"Prezența leziunilor carioase active pe dinții restanți."},{"id":"B","text":"Receptarea psihologică și funcțională a unei eventuale protezări mobile anterioare."},{"id":"C","text":"Calitatea relațiilor de colaborare avute anterior cu medicul dentist."},{"id":"D","text":"Cronologia extracțiilor dentare și etiologia pierderii dinților."},{"id":"E","text":"Debutul evoluției edentației și timpul scurs de la pierderea ultimilor dinți."}],"correct":["B","C","D","E"],"pages":[234],"source":"set-2"},{"id":"set2-5BuKauUs","fingerprint":"f60e5dc2478fd45b","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Cu ce elemente se corelează antecedentele personale generale (APG) în evaluarea unui pacient?","options":[{"id":"A","text":"Exclusiv cu medicația de fond administrată pentru afecțiunile sistemice."},{"id":"B","text":"Vârsta, sexul și stările fiziologice particulare, precum sarcina."},{"id":"C","text":"Ciclul menstrual la femei."},{"id":"D","text":"Momentul evolutiv biologic în care se află pacientul (creștere, maturitate, involuție)."},{"id":"E","text":"Preferințele pacientului privind materialele de restaurare protetică."}],"correct":["B","C","D"],"pages":[234],"source":"set-2"},{"id":"set2-Kg-hcIqU","fingerprint":"aa322d718ffbcac0","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afecțiuni generale sistemice sunt considerate de interes special, deoarece interferă cu patologia orală și tratamentul stomatologic?","options":[{"id":"A","text":"Afecțiuni ale sistemului nervos, cum ar fi epilepsia și boala Parkinson."},{"id":"B","text":"Afecțiuni oftalmologice, de exemplu miopia sau astigmatismul."},{"id":"C","text":"Afecțiuni dermatologice minore, cum ar fi eczema de contact."},{"id":"D","text":"Discrazii sanguine, incluzând anemiile, leucozele și sindroamele hemoragipare."},{"id":"E","text":"Afecțiuni ale aparatului digestiv precum gastritele, hepatitele cronice sau cirozele hepatice."}],"correct":["A","D","E"],"pages":[234],"source":"set-2"},{"id":"set2-OzJ0tc1v","fingerprint":"1c42d51ca4289466","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce precauții specifice trebuie luate în considerare în abordarea terapeutică orală a unui pacient cu un diagnostic de stare generală complexă?","options":[{"id":"A","text":"Planificarea ergonomică a ședințelor de tratament."},{"id":"B","text":"Evitarea manoperelor dureroase."},{"id":"C","text":"Administrarea medicației pentru patologia generală doar în zilele în care se efectuează tratament stomatologic."},{"id":"D","text":"Respectarea protocolului terapeutic pentru profilaxia endocarditei infecțioase, la pacienții cu risc."},{"id":"E","text":"Evitarea sistematică a oricărui tip de anestezie locală."}],"correct":["A","B","D"],"pages":[234],"source":"set-2"},{"id":"set2-mtML13e2","fingerprint":"176e13148a9b1276","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele reprezintă precauții în abordarea terapeutică protetică la un pacient cu o patologie generală asociată?","options":[{"id":"A","text":"Temporizarea manoperelor stomatologice până la stadiul de compensare al bolii generale."},{"id":"B","text":"Alegerea unei soluții anestezice fără vasoconstrictor."},{"id":"C","text":"Orientarea spre acrilate standard, cu conținut crescut de monomer, în cazul alergiei la acrilate."},{"id":"D","text":"Inițierea imediată a terapiei protetice, independent de identificarea afecțiunii generale de bază."},{"id":"E","text":"Aplicarea antibioterapiei de protecție pentru afecțiunile generale ce pot genera bacteremii tranzitorii în cazul manoperelor sângerânde."}],"correct":["A","B","E"],"pages":[235],"source":"set-2"},{"id":"set2-Sd4GjWdi","fingerprint":"e60cc964da1f35f2","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce factori sau terapii pot accentua atrofia osoasă, afectând astfel viabilitatea pe termen lung a unei proteze mobile?","options":[{"id":"A","text":"Terapia iradiantă."},{"id":"B","text":"Profilaxia endocarditei infecțioase."},{"id":"C","text":"Utilizarea acrilatelor flexibile, monomer-free."},{"id":"D","text":"Tulburările metabolice."},{"id":"E","text":"Terapia cortizonică."}],"correct":["A","D","E"],"pages":[235],"source":"set-2"},{"id":"set2-qWa0qg8U","fingerprint":"29ead242c5971483","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce informații relevante se obțin prin elaborarea istoricului stomatologic al unui pacient (antecedentele personale stomatologice)?","options":[{"id":"A","text":"Rata de afectare a patologiei orale."},{"id":"B","text":"Consemnarea eventualelor parafuncții existente, cum ar fi bruxismul."},{"id":"C","text":"Modul în care pacientul s-a acomodat cu o restaurare protetică mobilă anterioară."},{"id":"D","text":"Bolile mamei din perioada de sarcină."},{"id":"E","text":"Stereotipul de masticație și preferința pentru textura alimentelor."}],"correct":["A","B","C"],"pages":[235],"source":"set-2"},{"id":"set2-o1bQs-j6","fingerprint":"686f6d6e991e0a3e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"În cadrul antecedentelor heredo-colaterale (AHC) stomatologice, ce tip de afecțiuni cu transmitere genetică sunt de interes?","options":[{"id":"A","text":"Parodontopatiile și anomaliile dento-maxilare."},{"id":"B","text":"Bolile sistemice cu predispoziție ereditară care afectează ultimele 3 generații."},{"id":"C","text":"Alergia la acrilate."},{"id":"D","text":"Bolile cu caracter familial generate de condiții de mediu comune."},{"id":"E","text":"Tratamentele chirurgicale anterioare în sfera oro-maxilo-facială."}],"correct":["A"],"pages":[235],"source":"set-2"},{"id":"set2-jjFhCoiF","fingerprint":"fa6f1632b818fc0e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce aspecte sunt investigate în cadrul secțiunii referitoare la condițiile de viață și muncă ale unui pacient?","options":[{"id":"A","text":"Tipul de alimentație și preponderența hidrocarbonatelor."},{"id":"B","text":"Existența eventualelor ticuri profesionale."},{"id":"C","text":"Evoluția și importanța acordată de pacient patologiei orale."},{"id":"D","text":"Ritmul masticator și stereotipul de masticație (frecător, tocător, mixt)."},{"id":"E","text":"Bolile cu determinism genetic și cele cu risc de transmitere din familie."}],"correct":["A","B","D"],"pages":[235],"source":"set-2"},{"id":"set2-pcYiQ29v","fingerprint":"6d84f1682f4cf4da","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt metodele clasice utilizate în cadrul examenului clinic al aparatului dento-maxilar?","options":[{"id":"A","text":"Percuția"},{"id":"B","text":"Tomografia computerizată"},{"id":"C","text":"Palparea"},{"id":"D","text":"Auscultația"},{"id":"E","text":"Inspecția"}],"correct":["A","C","D","E"],"pages":[236],"source":"set-2"},{"id":"set2-LkldpP0N","fingerprint":"eb4d0b1e422951c6","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce modificări pot fi observate la inspecție în cazul edentațiilor întinse?","options":[{"id":"A","text":"Decolorarea tegumentelor periorale"},{"id":"B","text":"Înfundarea simetrică sau asimetrică a obrajilor"},{"id":"C","text":"Micșorarea etajului inferior al feței"},{"id":"D","text":"Asimetrii faciale"},{"id":"E","text":"Estomparea șanțurilor faciale"}],"correct":["B","C","D"],"pages":[236],"source":"set-2"},{"id":"set2-bUXgV37T","fingerprint":"b9bfb4a8123a1bab","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care este importanța clinică a identificării corecte a conturului feței?","options":[{"id":"A","text":"Ajută la stabilirea planului de simetrie median Tr-N-Sn."},{"id":"B","text":"Oferă informații despre eventualele hipertrofii sau spasme musculare."},{"id":"C","text":"Există o strânsă corelare între forma conturului și forma dinților, ghidând restaurările protetice."},{"id":"D","text":"Indică modificări ale etajului inferior al feței."},{"id":"E","text":"Permite determinarea tipului constituțional al pacientului (cerebral, digestiv etc.)."}],"correct":["C"],"pages":[236],"source":"set-2"},{"id":"set2-evCH_Keh","fingerprint":"f440b3b2c9a6fffb","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Prin ce puncte de reper anatomice se trasează imaginar planul de simetrie median al feței?","options":[{"id":"A","text":"Zy (dreapta) - Go (dreapta) - Go (stânga)"},{"id":"B","text":"N - Sn - Linia interincisivă maxilară"},{"id":"C","text":"Tragus (drept) - Comisura bucală (dreaptă) - Menton"},{"id":"D","text":"Zy (dreapta) - N - Zy (stânga)"},{"id":"E","text":"Tr - N - Sn"}],"correct":["E"],"pages":[236],"source":"set-2"},{"id":"set2-bWv21fdH","fingerprint":"1defcf7dab71de0d","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele pot constitui cauze ale asimetriilor faciale?","options":[{"id":"A","text":"Restaurări protetice incorect concepute"},{"id":"B","text":"Malrelațiile mandibulo-craniene"},{"id":"C","text":"Modificări de culoare ale tegumentelor"},{"id":"D","text":"Consolidările osoase vicioase"},{"id":"E","text":"Spasmele musculare sau hipertoniile"}],"correct":["A","B","D","E"],"pages":[236],"source":"set-2"},{"id":"set2-tbi5uPHD","fingerprint":"3865320714a871e3","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Conform analizei clinice, care dintre următoarele forme pot descrie conturul feței?","options":[{"id":"A","text":"Ovală"},{"id":"B","text":"Piramidală"},{"id":"C","text":"Trapezoidală"},{"id":"D","text":"Romboidală"},{"id":"E","text":"Pătrată"}],"correct":["A","C","E"],"pages":[236],"source":"set-2"},{"id":"set2-34Xtvfw_","fingerprint":"0d9cf60e506b07eb","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"În mod ideal, cu ce repere anatomice trebuie să coincidă planul de simetrie median al feței?","options":[{"id":"A","text":"Cu punctele paramediene Zy și Go"},{"id":"B","text":"Cu liniile interfrenulare și interincisive maxilară și mandibulară"},{"id":"C","text":"Cu planul de ocluzie"},{"id":"D","text":"Cu conturul feței, indiferent de forma acestuia"},{"id":"E","text":"Cu șanțurile anatomice faciale"}],"correct":["B"],"pages":[236],"source":"set-2"},{"id":"set2-ZiTztuU8","fingerprint":"3a35e1d77b7fdeab","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce puncte paramediene sunt utilizate ca referință pentru a evalua simetria facială în raport cu planul median?","options":[{"id":"A","text":"N (Nasion)"},{"id":"B","text":"Tr (Trichion)"},{"id":"C","text":"Go (Gonion)"},{"id":"D","text":"Sn (Subnasale)"},{"id":"E","text":"Zy (Zygion)"}],"correct":["C","E"],"pages":[236],"source":"set-2"},{"id":"set2-vg8mqYfs","fingerprint":"a5b4d5f2be50db0b","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afirmații referitoare la dimensiunea verticală a etajului inferior sunt adevărate?","options":[{"id":"A","text":"În relație de postură, etajul inferior poate fi mărit ca urmare a hipotoniei mușchilor ridicători."},{"id":"B","text":"Pierderea stopurilor centrice laterale este o cauză de micșorare a etajului inferior în relație centrică."},{"id":"C","text":"Supradimensionarea etajului inferior este imposibilă, modificarea fiind întotdeauna în sensul subdimensionării."},{"id":"D","text":"În relație centrică, etajul inferior se micșorează în cazul spasmelor musculare pe mușchii ridicători."},{"id":"E","text":"O diferență normală între dimensiunea măsurată în relație de postură și cea în relație centrică este de 2 - 4 mm."}],"correct":["A","B","E"],"pages":[237],"source":"set-2"},{"id":"set2-EoIQPXUp","fingerprint":"d840805f2779ba7c","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce elemente sunt evaluate în cadrul inspecției de profil?","options":[{"id":"A","text":"Postura buzelor, care poate fi protruzivă sau retruzivă."},{"id":"B","text":"Treapta labială, care poate fi accentuată în cazul retrognațiilor."},{"id":"C","text":"Unghiul nazo-labial, a cărui valoare normală este de 90°."},{"id":"D","text":"Temperatura și umiditatea tegumentelor."},{"id":"E","text":"Punctele de emergență ale trigemenului și glandele salivare mari."}],"correct":["A","B","C"],"pages":[237],"source":"set-2"},{"id":"set2-1HwRUKJi","fingerprint":"3fe85b0a98fcf4c4","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce poate indica prezența temperaturii scăzute a tegumentelor, însoțită de transpirații reci, la palparea superficială?","options":[{"id":"A","text":"O hipertonie a mușchilor ridicători ai mandibulei."},{"id":"B","text":"O afecțiune generală care se constituie într-o urgență."},{"id":"C","text":"O leziune inflamatorie localizată."},{"id":"D","text":"O parestezie în teritoriul nervului trigemen."},{"id":"E","text":"O stare de deshidratare a tegumentelor."}],"correct":["B"],"pages":[237],"source":"set-2"},{"id":"set2-MqG-GojV","fingerprint":"3b878f4bac88c3a7","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afirmații despre palparea profundă sunt corecte?","options":[{"id":"A","text":"Manevrele Netter se referă la palparea dinamică a mușchilor cu gura deschisă, opunându-se mișcărilor funcționale."},{"id":"B","text":"Tehnica de palpare prin pensare este utilizată pentru a evalua elasticitatea țesutului subcutanat."},{"id":"C","text":"Include examinarea punctelor de emergență ale trigemenului, reliefurilor osoase și glandelor salivare mari."},{"id":"D","text":"Palparea mușchilor se efectuează atât static, în repaus postural, cât și dinamic."},{"id":"E","text":"Sensibilitatea termică este evaluată simetric cu eprubete cu apă rece în cadrul acestei etape."}],"correct":["A","C","D"],"pages":[237],"source":"set-2"},{"id":"set2-yE_ohBSN","fingerprint":"31cef09a21b2642e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care dintre următoarele situații poate conduce la mărirea etajului inferior al feței în relație centrică?","options":[{"id":"A","text":"Hipotonii musculare pe mușchii ridicători."},{"id":"B","text":"Edentații cu instalarea ocluziei prăbușite."},{"id":"C","text":"Infraalveolia zonelor laterale cu ocluzie adâncă."},{"id":"D","text":"Refaceri protetice defectuoase în zonele laterale."},{"id":"E","text":"Hipotonii pe mușchii coborâtori."}],"correct":["D"],"pages":[237],"source":"set-2"},{"id":"set2-gd3C3IYw","fingerprint":"6c02b0c1689e0f28","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"În ce context clinic poate apărea o inversare a treptei labiale?","options":[{"id":"A","text":"În situația unui șanț labio-mentonier șters."},{"id":"B","text":"În prezența unei ocluzii inverse frontale."},{"id":"C","text":"Când unghiul gonial are o valoare de 130-140°."},{"id":"D","text":"La un pacient cu retrognație mandibulară."},{"id":"E","text":"În cazul unei proalveolodonții."}],"correct":["B"],"pages":[237],"source":"set-2"},{"id":"set2-VpEmPpbk","fingerprint":"fd79dd98f6902b55","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele elemente sunt evaluate în timpul inspecției dinamice a articulației temporo-mandibulare?","options":[{"id":"A","text":"Traiectoria de mișcare a mentonului"},{"id":"B","text":"Excursiile condiliene"},{"id":"C","text":"Modificările de culoare și integritate ale regiunii pretragiene"},{"id":"D","text":"Amplitudinea deschiderii gurii"},{"id":"E","text":"Simetria arcului Cupidon"}],"correct":["A","B","D"],"pages":[238],"source":"set-2"},{"id":"set2-si8rNCq8","fingerprint":"477882492655769e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Unde este localizat punctul de reper pentru palparea regiunii pretragiene a articulației temporo-mandibulare?","options":[{"id":"A","text":"Direct pe tragus, pentru a percepe mișcarea condilului"},{"id":"B","text":"La 13 mm anterior de tragus, pe linia ce unește unghiul extern al ochiului cu tragusul"},{"id":"C","text":"La 13 mm anterior de tragus, pe linia ce unește unghiul intern al ochiului cu tragusul"},{"id":"D","text":"La 10 mm anterior de tragus, pe linia ce unește unghiul extern al ochiului cu tragusul"},{"id":"E","text":"La 13 mm posterior de tragus, pe linia ce unește unghiul extern al ochiului cu tragusul"}],"correct":["B"],"pages":[238],"source":"set-2"},{"id":"set2-IWtFaGDD","fingerprint":"4516015b2f0bac83","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce permite evaluarea prin metoda de palpare bidigitală cu indexurile în canalele auditive externe?","options":[{"id":"A","text":"Prezența cracmentelor și crepitațiilor"},{"id":"B","text":"Simetria și amplitudinea excursiilor condiliene"},{"id":"C","text":"Traiectoria de rotație pură condiliană"},{"id":"D","text":"Sensibilitatea regiunii pretragiene"},{"id":"E","text":"Poziția condililor în ocluzie centrică"}],"correct":["C"],"pages":[238],"source":"set-2"},{"id":"set2-KHKulbXo","fingerprint":"0408d20c7ed8ac0d","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Cum se procedează pentru a decela sensibilitatea elementelor articulare ale ATM?","options":[{"id":"A","text":"Prin palparea bidigitală a canalelor auditive externe în timpul mișcărilor de lateralitate"},{"id":"B","text":"Prin auscultație directă a regiunii pretragiene în timpul deschiderii maxime a gurii"},{"id":"C","text":"Prin executarea de presiuni pe menton în sens postero-superior, în timp ce pacientul are gura întredeschisă"},{"id":"D","text":"Prin aplicarea de presiuni pe regiunea pretragiană cu cele patru degete, cu gura în poziție de repaus"},{"id":"E","text":"Prin aplicarea de presiuni pe menton în sens antero-inferior, cu gura închisă în ocluzie centrică"}],"correct":["C"],"pages":[238],"source":"set-2"},{"id":"set2-33sF2XyE","fingerprint":"2f9688f660ceadda","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afirmații despre examenul articulației temporo-mandibulare (ATM) sunt adevărate?","options":[{"id":"A","text":"Palparea permite aprecierea simetriei, sinergiei și amplitudinii excursiilor condiliene."},{"id":"B","text":"Auscultația poate fi realizată direct sau indirect și poate decela cracmente și crepitații."},{"id":"C","text":"Palparea cu patru degete pretragian evaluează traiectoria de rotație pură condiliană."},{"id":"D","text":"Examenul ATM se realizează independent de examenul mușchilor și al ocluziei."},{"id":"E","text":"Inspecția statică se realizează doar la nivelul regiunii pretragiene, din față."}],"correct":["A","B"],"pages":[238],"source":"set-2"},{"id":"set2-brTPYyCa","fingerprint":"8b1351cea946cadc","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce elemente sunt evaluate în cadrul examenului static al orificiului cavității orale?","options":[{"id":"A","text":"Culoarea și textura labială"},{"id":"B","text":"Poziția condililor"},{"id":"C","text":"Amplitudinea deschiderii gurii"},{"id":"D","text":"Raportul bilabial sau treapta labială"},{"id":"E","text":"Simetria arcului Cupidon"}],"correct":["A","D","E"],"pages":[238],"source":"set-2"},{"id":"set2-7JCTaISS","fingerprint":"91c5c4277cfae42b","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"În cadrul examenului clinic al cavității orale, care dintre următoarele structuri se examinează imediat după arcadele dentare?","options":[{"id":"A","text":"Limba"},{"id":"B","text":"Palatul dur și moale"},{"id":"C","text":"Mucoasa jugală"},{"id":"D","text":"Suportul odontal"},{"id":"E","text":"Vestibulul cavității orale"}],"correct":["D"],"pages":[238],"source":"set-2"},{"id":"set2-nUy284J5","fingerprint":"ad83506a7d71a97f","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt elementele evaluate în cadrul examenului static al orificiului cavității orale?","options":[{"id":"A","text":"Culoarea și textura labială"},{"id":"B","text":"Raportul bilabial sau treapta labială"},{"id":"C","text":"Fanta labială"},{"id":"D","text":"Simetria arcului Cupidon"},{"id":"E","text":"Amplitudinea deschiderii cavității orale"}],"correct":["A","B","C","D"],"pages":[228,238],"source":"set-2"},{"id":"set2-_4MexwuR","fingerprint":"dd37f6ab1c7d7f43","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt motivele menționate pentru care abordarea terapeutică în anumite contexte socio-economice se orientează spre extracție în defavoarea tratamentelor conservatoare?","options":[{"id":"A","text":"Considerente de ordin financiar"},{"id":"B","text":"Preferința medicului pentru proceduri chirurgicale"},{"id":"C","text":"Eficiența superioară a extracției pe termen lung"},{"id":"D","text":"Riscul crescut de complicații al tratamentelor conservatoare"},{"id":"E","text":"Evitarea ședințelor de tratament numeroase"}],"correct":["A","E"],"pages":[228],"source":"set-2"},{"id":"set2-at60fLwR","fingerprint":"b83b29279fd664a8","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele sunt considerate complicații loco-regionale ale edentației parțiale întinse (EPI), ce apar în cascadă după modificările locale?","options":[{"id":"A","text":"Disfuncțiile cranio-mandibulare"},{"id":"B","text":"Malocluziile"},{"id":"C","text":"Înfundarea obrajilor sau a buzelor"},{"id":"D","text":"Migrările dentare în plan orizontal și vertical"},{"id":"E","text":"Modificarea parametrilor spațiilor protetice potențiale"}],"correct":["A","B"],"pages":[228],"source":"set-2"},{"id":"set2-LPrHqPB1","fingerprint":"4b1ef71f9a332c66","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce modificare a aspectului facial este considerată un marker al dezechilibrelor ocluzo-articulare în edentația parțială întinsă?","options":[{"id":"A","text":"Modificarea texturii labiale"},{"id":"B","text":"Asimetria arcului Cupidon"},{"id":"C","text":"Înfundarea buzelor"},{"id":"D","text":"Subdimensionarea etajului inferior"},{"id":"E","text":"Înfundarea obrajilor"}],"correct":["D"],"pages":[228],"source":"set-2"},{"id":"set2-yC574jUH","fingerprint":"4ce45999b0449a30","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care sunt principalele două capitole de semne subiective care determină pacientul cu edentație parțială întinsă să se prezinte la medicul dentist?","options":[{"id":"A","text":"Migrări dentare și aspectul inestetic"},{"id":"B","text":"Modificări ale aspectului facial și durerea cronică"},{"id":"C","text":"Fenomenul dureros și deficiențele funcționale"},{"id":"D","text":"Durerea acută și instabilitatea ocluzală"},{"id":"E","text":"Disfuncții cranio-mandibulare și malocluzii"}],"correct":["C"],"pages":[228],"source":"set-2"},{"id":"set2-pwuD80OL","fingerprint":"f788d928c7ea17bf","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele substanțe sunt menționate ca fiind algogenice, stimulând nociceptorii periferici în durerea acută?","options":[{"id":"A","text":"Prostaglandinele"},{"id":"B","text":"Bradikinina"},{"id":"C","text":"Substanța P"},{"id":"D","text":"Dopamina"},{"id":"E","text":"Histamina"}],"correct":["A","B","C","E"],"pages":[228],"source":"set-2"},{"id":"set2-tV-VCyIK","fingerprint":"9729d9c8a420edb6","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele elemente fac parte din etapele de elaborare a diagnosticului loco-regional al edentației parțiale?","options":[{"id":"A","text":"Diagnosticul stării generale a pacientului."},{"id":"B","text":"Statusul de igienă oro-dentară, incluzând indicii de placă și tartru."},{"id":"C","text":"Planul de tratament protetic final."},{"id":"D","text":"Diagnosticul de integritate sau afectare musculară."},{"id":"E","text":"Diagnosticul pulpar și odontal."}],"correct":["A","B","D","E"],"pages":[247],"source":"set-2"},{"id":"set2-j-5jtIoB","fingerprint":"14075ac4a45e9ca6","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce forme de durere sunt incluse sub denumirea generică de durere fiziologică?","options":[{"id":"A","text":"Durerea acută"},{"id":"B","text":"Durerea viscerală"},{"id":"C","text":"Durerea cronică"},{"id":"D","text":"Durerea somatică"},{"id":"E","text":"Durerea neuropată"}],"correct":["B","D","E"],"pages":[228],"source":"set-2"},{"id":"set2-VhIaXYAm","fingerprint":"2134bd6c1de5eb8b","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele situații clinice pot determina o asimetrie a arcului Cupidon?","options":[{"id":"A","text":"Edentații terminale unilaterale"},{"id":"B","text":"Trismus de maseter"},{"id":"C","text":"Laxitatea capsulo-ligamentară la ATM"},{"id":"D","text":"Edentații frontale paramediene"},{"id":"E","text":"Ectopii de canin"}],"correct":["D","E"],"pages":[239],"source":"set-2"},{"id":"set2-YwTyskSA","fingerprint":"c012d71faafcc318","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce modificare se poate observa la inspecția buzei superioare în cazul edentațiilor frontale cu absența mai multor dinți succesivi?","options":[{"id":"A","text":"O deviere a mentonului la deschiderea gurii"},{"id":"B","text":"O înfundare a buzei cu micșorarea roșului buzei"},{"id":"C","text":"Prezența corpusculilor Fordyce"},{"id":"D","text":"Prolabarea mucoasei spre spațiul edentat"},{"id":"E","text":"O amplitudine mărită a deschiderii cavității orale"}],"correct":["B"],"pages":[239],"source":"set-2"},{"id":"set2-s_BslfB5","fingerprint":"14ce56354cd36b6b","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele condiții pot conduce la o micșorare a amplitudinii deschiderii cavității orale?","options":[{"id":"A","text":"Trismusul de maseter"},{"id":"B","text":"Anchiloza ATM"},{"id":"C","text":"Fracturile condiliene"},{"id":"D","text":"Parezele faciale"},{"id":"E","text":"Laxitatea capsulo-ligamentară la ATM"}],"correct":["A","B","C"],"pages":[239],"source":"set-2"},{"id":"set2-BFk05P3k","fingerprint":"5561520edf95fb15","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce factori pot determina o deviere a mentonului, afectând simetria deschiderii cavității orale?","options":[{"id":"A","text":"Ticurilor de succiune"},{"id":"B","text":"Edentații parțiale întinse uniterminale (clasa I și a II-a Kennedy)"},{"id":"C","text":"Paralizii și pareze faciale"},{"id":"D","text":"Microstomia"},{"id":"E","text":"Afecțiuni ce interesează ATM"}],"correct":["B","C","E"],"pages":[239],"source":"set-2"},{"id":"set2-OOq3on1H","fingerprint":"2d54e43fd652cda0","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce elemente specifice se urmăresc în cadrul examenului mucoasei labio-jugale?","options":[{"id":"A","text":"Inserția frenurilor și plicilor alveolo-jugale"},{"id":"B","text":"Prezența amprentei dinților și a interliniului articular"},{"id":"C","text":"Aspectul zonelor funcționale periferice"},{"id":"D","text":"Prezența corpusculilor Fordyce în vecinătatea canalului Stenon"},{"id":"E","text":"Aspectul canalului Stenon și permeabilitatea sa"}],"correct":["B","D","E"],"pages":[239],"source":"set-2"},{"id":"set2-3WCIOOKZ","fingerprint":"7cb14a6563a9a46e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"În ce situație clinică este absolut obligatorie descrierea zonelor funcționale periferice adiacente spațiului protetic potențial?","options":[{"id":"A","text":"În toate cazurile de edentație parțială întinsă (EPI)"},{"id":"B","text":"În prezența unor bride sau cicatrici vestibulare"},{"id":"C","text":"La pacienții cu ticuri de succiune și prolabare a mucoasei"},{"id":"D","text":"În edentațiile frontale cu înfundarea buzei superioare"},{"id":"E","text":"În cazul edentațiilor terminale care apelează la o protezare parțială amovibilă"}],"correct":["E"],"pages":[239],"source":"set-2"},{"id":"set2-7vrFUxMq","fingerprint":"40aa36af67f5518a","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt afirmațiile corecte referitoare la caracteristicile zonelor funcționale periferice în edentația parțială întinsă (EPI)?","options":[{"id":"A","text":"Se examinează atât static, cât și dinamic prin mobilizarea țesuturilor de la periferia câmpului protetic."},{"id":"B","text":"Pot fi scurtate sau întrerupte de prezența unităților odonto-parodontale."},{"id":"C","text":"Evaluarea lor se face exclusiv prin inspecție, fără a necesita palpare."},{"id":"D","text":"Se succed întotdeauna într-o ordine clară, similar edentației totale."},{"id":"E","text":"Numărul lor este fix, indiferent de topografia edentației."}],"correct":["A","B"],"pages":[239],"source":"set-2"},{"id":"set2-fQ_Nf_uN","fingerprint":"443b0768e4b001ef","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Prin ce manevră se apreciază corect înălțimea pungii Eisenring?","options":[{"id":"A","text":"Prin bascularea mandibulei spre zona examinată"},{"id":"B","text":"Prin tracționarea spre posterior a buzei superioare"},{"id":"C","text":"Prin palpare cu fuloarul din aproape în aproape"},{"id":"D","text":"Prin bascularea mandibulei de partea opusă examinării"},{"id":"E","text":"Prin îndepărtarea cu oglinda a țesuturilor moi"}],"correct":["A"],"pages":[239],"source":"set-2"},{"id":"set2-E37tr4Zq","fingerprint":"58f549ef68db6c67","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt afirmațiile corecte referitoare la examinarea și caracteristicile zonei „Ah”?","options":[{"id":"A","text":"Poziția verticală a vălului palatin este considerată cea mai favorabilă pentru succiune."},{"id":"B","text":"Examinarea dinamică se realizează prin punerea în tensiune a vălului palatin prin manevra Valsalva și emisia vocalei „A”."},{"id":"C","text":"Palparea se efectuează cu fuloarul dinspre posterior spre anterior și de la stânga spre dreapta."},{"id":"D","text":"Este o zonă cheie periferică de închidere marginală cu rol în realizarea succiunii."},{"id":"E","text":"Valoarea clinică a zonei variază în funcție de poziția vălului palatin."}],"correct":["B","D","E"],"pages":[240],"source":"set-2"},{"id":"set2-DrEu2shJ","fingerprint":"916608a1be970a2c","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce poziție a vălului palatin este considerată cea mai favorabilă pentru realizarea succiunii interne și externe?","options":[{"id":"A","text":"Medio-laterală"},{"id":"B","text":"Orizontală"},{"id":"C","text":"Verticală"},{"id":"D","text":"Antero-posterioară"},{"id":"E","text":"Oblică"}],"correct":["E"],"pages":[240],"source":"set-2"},{"id":"set2-Wj1hMKXN","fingerprint":"56d65baa3abdeafd","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afirmații descriu corect zona vestibulară laterală mandibulară (punga lui Fisch)?","options":[{"id":"A","text":"Este dominată de inserția mușchiului genioglos."},{"id":"B","text":"Este o zonă cheie de închidere marginală, similară zonei „Ah” de la maxilar."},{"id":"C","text":"Se examinează cu gura larg deschisă pentru o vizualizare optimă."},{"id":"D","text":"Este dominată de inserția mușchiului buccinator."},{"id":"E","text":"Permite îngroșări ale marginilor protezei pentru ameliorarea menținerii și stabilității."}],"correct":["D","E"],"pages":[240],"source":"set-2"},{"id":"set2-Ad9O21on","fingerprint":"426fb3e910edd85c","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce caracteristici sunt specifice zonei linguale centrale (ZLC) mandibulare?","options":[{"id":"A","text":"Inserția posterioară a limbii micșorează considerabil dimensiunile zonei."},{"id":"B","text":"Este considerată o zonă cheie de închidere marginală, similară zonei „Ah” de la maxilar."},{"id":"C","text":"Inserția anterioară a limbii mărește dimensiunile zonei și scade gradul de mobilitate."},{"id":"D","text":"Mobilitatea sa este crescută de tracțiunile exercitate de frenul lingual în cazul unei inserții anterioare a limbii."},{"id":"E","text":"Este dominată de inserția mușchiului milohioidian."}],"correct":["A","B","D"],"pages":[240],"source":"set-2"},{"id":"set2-o3FuKYKs","fingerprint":"a0c99950b892d0d1","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Privind examinarea și particularitățile zonei linguale laterale (ZLL), care afirmații sunt adevărate?","options":[{"id":"A","text":"În zona premolară se poate palpa torusul mandibular pe versantul intern al crestei."},{"id":"B","text":"Zona este dominată de inserția mușchiului genioglos."},{"id":"C","text":"Prezența unei linii oblice interne retentive permite o extindere mai mare a marginii protetice."},{"id":"D","text":"Palparea digitală poate aprecia profunzimea și inserția mușchiului milohioidian."},{"id":"E","text":"Examinarea dinamică implică indicarea pacientului să execute mișcări de ridicare și balansare a limbii."}],"correct":["A","D","E"],"pages":[240],"source":"set-2"},{"id":"set2-I9vupkej","fingerprint":"09280425eff7a4f1","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce metodologie generală este utilizată pentru examinarea zonelor funcționale periferice linguale mandibulare?","options":[{"id":"A","text":"Static prin inspecție și palpare, și dinamic prin mobilizarea limbii."},{"id":"B","text":"Doar prin palpare digitală, pentru a evalua inserțiile musculare."},{"id":"C","text":"Exclusiv prin inspecție statică, cu gura larg deschisă."},{"id":"D","text":"Prin manevra Valsalva și emisia de vocale."},{"id":"E","text":"Prin eversarea buzei inferioare și observarea inserției frenului."}],"correct":["A"],"pages":[240],"source":"set-2"},{"id":"set2-XKXNzGgx","fingerprint":"c5a554a48b37caae","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următorii parametri sunt evaluați în cadrul examenului suportului parodontal?","options":[{"id":"A","text":"Aspectul gingiei"},{"id":"B","text":"Mobilitatea dentară"},{"id":"C","text":"Existența sângerării la sondaj"},{"id":"D","text":"Morfologia coronară"},{"id":"E","text":"Importanța pierderii de atașament"}],"correct":["A","B","C","E"],"pages":[241],"source":"set-2"},{"id":"set2-N9GduA9q","fingerprint":"1a5ef5d5846aa5d8","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce parametri ai spațiului protetic potențial (SPP) se măsoară cu ajutorul șublerului sau al pensei dentare și al riglei?","options":[{"id":"A","text":"Amplitudinea"},{"id":"B","text":"Reziliența mucoasei"},{"id":"C","text":"Înălțimea"},{"id":"D","text":"Lățimea"},{"id":"E","text":"Limitele"}],"correct":["A","C","D","E"],"pages":[241],"source":"set-2"},{"id":"set2-a6YnK5t1","fingerprint":"6c7a5bc258ba5c3f","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce consecință directă poate avea hipertrofia polului inferior al tuberozității maxilare?","options":[{"id":"A","text":"Ameliorarea stabilității protezelor mobilizabile"},{"id":"B","text":"Creșterea retentivității versantului vestibular"},{"id":"C","text":"Micșorarea sau anularea spațiului protetic potențial (SPP)"},{"id":"D","text":"Apariția unor discontinuități osoase la palpare"},{"id":"E","text":"Limitarea distală a extinderii protezei de către ligamentul pterigo-mandibular"}],"correct":["C"],"pages":[241],"source":"set-2"},{"id":"set2-ZzfKEtKS","fingerprint":"fb1f8e169b8f3c04","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afirmații referitoare la zona de sprijin mandibulară în edentația parțială întinsă sunt corecte?","options":[{"id":"A","text":"Componentele sale principale sunt tuberculul piriform și creasta edentată."},{"id":"B","text":"Versanții crestei edentate reprezintă zona primară de sprijin."},{"id":"C","text":"Include obligatoriu tuberculul piriform în structura protezei mobilizabile."},{"id":"D","text":"Ligamentul pterigo-mandibular constituie zona primară de sprijin."},{"id":"E","text":"Este mai extinsă comparativ cu zona de sprijin maxilară."}],"correct":["A","C"],"pages":[241],"source":"set-2"},{"id":"set2-vQ4ozSRH","fingerprint":"659dba48eb372c67","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce afirmație descrie corect relația dintre continuitatea arcadei dentare și statusul de edentație?","options":[{"id":"A","text":"Păstrarea punctelor de contact între dinți garantează prezența tuturor unităților odonto-parodontale."},{"id":"B","text":"Examinarea continuității arcadei este suficientă pentru a confirma sau infirma prezența tuturor dinților."},{"id":"C","text":"O protezare fixă elimină complet edentația, restaurând funcțional și anatomic arcada."},{"id":"D","text":"Leziunea anatomică prin absența dinților poate coexista cu o arcadă aparent continuă."},{"id":"E","text":"O arcadă cu continuitate refăcută artificial printr-o proteză fixă nu mai prezintă o leziune anatomică de edentație."}],"correct":["D"],"pages":[241],"source":"set-2"},{"id":"set2-Q7ZIlflg","fingerprint":"a2820e3b3c749ea8","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"În cuantificarea aspectelor crestei edentate și a fibromucoasei acoperitoare în edentația parțială, ce sisteme de clasificare sunt menționate ca fiind utile?","options":[{"id":"A","text":"Indicele de mobilitate dentară pentru fibromucoasă"},{"id":"B","text":"Clasificarea Atwood pentru creasta edentată"},{"id":"C","text":"Indicii Lejoyeux pentru fibromucoasă"},{"id":"D","text":"Clasificarea Atwood pentru fibromucoasă"},{"id":"E","text":"Indicii Lejoyeux pentru retentivitatea crestei"}],"correct":["B","C"],"pages":[241],"source":"set-2"},{"id":"set2-EyHnRG_u","fingerprint":"80fe19f3db747e31","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele elemente fac parte din examinarea suportului odontal?","options":[{"id":"A","text":"Existența sângerării la sondaj"},{"id":"B","text":"Vitalitatea și tratamentele odontale existente"},{"id":"C","text":"Importanța pierderii de atașament"},{"id":"D","text":"Poziția pe arcadă și punctul de contact"},{"id":"E","text":"Culoarea și morfologia coronară"}],"correct":["B","D","E"],"pages":[241],"source":"set-2"},{"id":"set2-FjmKu014","fingerprint":"4e13a24e2ee8f4b3","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afirmații despre examinarea crestei edentate sunt corecte?","options":[{"id":"A","text":"Indicele Schröder este utilizat pentru aprecierea atrofiei osoase mandibulare."},{"id":"B","text":"Versanții crestei reprezintă zona secundară de sprijin."},{"id":"C","text":"Tuberculii piriformi sunt zone biostatice care își conservă în general volumul și forma."},{"id":"D","text":"Indicele Koller-Russov se utilizează pentru evaluarea rezilienței mucoasei."},{"id":"E","text":"Muchia crestei este considerată zona primară de sprijin."}],"correct":["B","C","E"],"pages":[242],"source":"set-2"},{"id":"set2-vCCB6ieX","fingerprint":"03f60061467dcdf6","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce aspecte specifice se evaluează la nivelul restaurărilor protetice fixe în timpul examenului clinic?","options":[{"id":"A","text":"Stabilitatea statică și dinamică."},{"id":"B","text":"Materialul din care sunt realizate și concepția generală."},{"id":"C","text":"Raportul corpului de punte cu tuberculii piriformi."},{"id":"D","text":"Rapoartele cu dinții restanți și cu arcada antagonistă."},{"id":"E","text":"Adaptarea cervicală și ocluzală a elementelor de agregare."}],"correct":["E"],"pages":[242],"source":"set-2"},{"id":"set2-KrDu88hQ","fingerprint":"1488b667dd4ddaa0","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele elemente sunt evaluate în cadrul examenului bolții palatine?","options":[{"id":"A","text":"Prezența de spiculi osoși la nivelul șanțurilor alveolo-palatine."},{"id":"B","text":"Mărimea și poziția torusului palatin, încadrat în clasificarea Landa."},{"id":"C","text":"Modalitatea de inserție a mușchiului genioglos."},{"id":"D","text":"Înălțimea și înclinarea versantului lingual al arcului anterior mandibular."},{"id":"E","text":"Reliefarea, simetria, numărul și dispoziția rugilor palatine."}],"correct":["A","B","E"],"pages":[242],"source":"set-2"},{"id":"set2-l1SPsZbw","fingerprint":"a6f6c54b036549a9","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce factor influențează direct tipul de ocluzie artificială ce va fi realizat?","options":[{"id":"A","text":"Prezența și mărimea torusului palatin."},{"id":"B","text":"Poziția limbii în repaus."},{"id":"C","text":"Indicele de reziliență al suportului fibromucos."},{"id":"D","text":"Valoarea unghiului interalveolar."},{"id":"E","text":"Numărul și dispoziția rugilor palatine."}],"correct":["D"],"pages":[242],"source":"set-2"},{"id":"set2-e6q8kvDY","fingerprint":"5509a547d908006d","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"În ce constă examinarea unui pacient purtător de proteze mobilizabile bimaxilar?","options":[{"id":"A","text":"O a doua etapă intraorală, unde se urmărește menținerea, stabilitatea și funcționalitatea protezelor."},{"id":"B","text":"Se utilizează indicele Landa pentru a cuantifica stabilitatea protezelor."},{"id":"C","text":"O primă etapă extraorală, în care se apreciază calitățile bazei și ale arcadelor artificiale."},{"id":"D","text":"Evaluarea este considerată completă după analiza ocluzală, care este opțională."},{"id":"E","text":"Examinarea rapoartelor ocluzale statice și dinamice artificiale."}],"correct":["A","C","E"],"pages":[242],"source":"set-2"},{"id":"set2-2t4pwCZa","fingerprint":"4f94236ca4b18b3e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care este considerată cea mai favorabilă poziție a limbii în repaus?","options":[{"id":"A","text":"Retractată posterior."},{"id":"B","text":"Superioară, în contact complet cu bolta palatină."},{"id":"C","text":"Laterală, sprijinită pe arcadele dentare."},{"id":"D","text":"Anterioară, cu vârful sprijinit pe dinții frontali."},{"id":"E","text":"Intermediară."}],"correct":["E"],"pages":[242],"source":"set-2"},{"id":"set2-YjaJSybr","fingerprint":"d93ed61107ec0542","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care dintre următoarele NU reprezintă un parametru ocluzal analizat în scopul stabilirii unui diagnostic și plan de tratament?","options":[{"id":"A","text":"Curba de ocluzie transversală (Monson și Villain)"},{"id":"B","text":"Sistemul T-Scan"},{"id":"C","text":"Morfologia ariilor ocluzale"},{"id":"D","text":"Planul de ocluzie"},{"id":"E","text":"Cuspizii de sprijin"}],"correct":["B"],"pages":[243],"source":"set-2"},{"id":"set2-tDG8vvA4","fingerprint":"2fd35400f82e7862","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Conform caracteristicilor unei ocluzii normale ideale, care afirmație descrie corect tipul și distribuția contactelor dento-dentare?","options":[{"id":"A","text":"Contactele trebuie să fie de tipul cuspid-pantă cuspidiană, localizate exclusiv la nivel molar."},{"id":"B","text":"Contactele trebuie să fie unice, pentru a evita suprasolicitarea, și realizate între suprafețe concave."},{"id":"C","text":"Contactele trebuie să fie de tipul margine incizală – fosetă și localizate cu aproximație."},{"id":"D","text":"Contactele trebuie să fie multiple, stabile și realizate între suprafețe netede și convexe."},{"id":"E","text":"Contactele trebuie să fie liniare și distribuite neuniform pe arcadă."}],"correct":["D"],"pages":[243],"source":"set-2"},{"id":"set2-Dvr7Az_e","fingerprint":"b85a4b7b03b38d18","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"În ce poziții mandibulare se realizează marcarea și înregistrarea contactelor dento-dentare pentru a fi transferate pe fișele de analiză ocluzală?","options":[{"id":"A","text":"În ocluzia terminală centrică și ocluzia terminală posturală."},{"id":"B","text":"În relație centrică (RC) și în intercuspidare maximă (IM)."},{"id":"C","text":"Doar în relație centrică (RC), deoarece este o poziție reproductibilă."},{"id":"D","text":"Doar în intercuspidare maximă (IM), deoarece reprezintă contactul maxim."},{"id":"E","text":"În pozițiile point-centric, wide-centric și long-centric."}],"correct":["B"],"pages":[243],"source":"set-2"},{"id":"set2-wuCGKYCn","fingerprint":"0fc240ebd0dba0ee","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care sunt cele două traiectorii de închidere a mandibulei care prezintă semnificație funcțională și definesc ocluzia terminală?","options":[{"id":"A","text":"Traiectoria de închidere în relație centrică și traiectoria de închidere posturală."},{"id":"B","text":"Traiectoria de închidere musculară și traiectoria de închidere posturală."},{"id":"C","text":"Traiectoria de închidere haotică și traiectoria de închidere în intercuspidare maximă."},{"id":"D","text":"Traiectoria ligamentară și traiectoria centrică."},{"id":"E","text":"Traiectoria de rotație pură și traiectoria musculară."}],"correct":["A"],"pages":[243],"source":"set-2"},{"id":"set2-oTFDcdgu","fingerprint":"39ef74296c3371b2","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce informații suplimentare poate aduce examenul paraclinic al modelului de studiu în comparație cu inspecția clinică directă la pacient?","options":[{"id":"A","text":"Consemnarea rapoartelor ocluzale interarcadice de tip Angle."},{"id":"B","text":"Observarea ciclurilor masticatorii modificate la edentatul parțial."},{"id":"C","text":"Posibilitatea vizualizării directe a contactelor și a morfologiei cuspidiene."},{"id":"D","text":"Înregistrarea dinamică a contactelor prin intermediul sistemului T-Scan."},{"id":"E","text":"Evidențierea contactelor dento-dentare cu ajutorul hârtiei de articulație."}],"correct":["C"],"pages":[243],"source":"set-2"},{"id":"set2-gcTzJ3mE","fingerprint":"4e63e95f84f5f71e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt afirmațiile corecte cu privire la spațiul de inocluzie fiziologică?","options":[{"id":"A","text":"Se măsoară prin trasarea unei linii ce corespunde marginii incizale a incisivilor superiori pe fața vestibulară a celor mandibulari, cu mandibula în relație centrică (RC)."},{"id":"B","text":"Este un reper fundamental doar în cazul edentației parțiale întinse."},{"id":"C","text":"În zona laterală, dimensiunea normală este de 1,8 - 2,7 mm."},{"id":"D","text":"Valoarea sa în zona laterală este identică cu cea din zona frontală."},{"id":"E","text":"Valoarea sa normală în zona frontală este de 2 - 4 mm."}],"correct":["C","E"],"pages":[244],"source":"set-2"},{"id":"set2-ty_Oy8VK","fingerprint":"de691eff01db0dd7","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce fenomen descrie dezocluzia dinților din zona laterală în timpul mișcării de protruzie, cu preluarea mișcării de către panta retroincisivă?","options":[{"id":"A","text":"Fenomen Christensen sagital"},{"id":"B","text":"Point Centric"},{"id":"C","text":"Fenomen Christensen lateral"},{"id":"D","text":"Triunghiul de toleranță ocluzală al lui Spirgi"},{"id":"E","text":"Long Centric"}],"correct":["A"],"pages":[244],"source":"set-2"},{"id":"set2-uHUUVcia","fingerprint":"7d34479e6564ce66","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce consecințe patologice pot apărea în cazul păstrării contactelor dentare pe partea inactivă în timpul mișcării de lateralitate?","options":[{"id":"A","text":"Inducerea fenomenului Christensen sagital."},{"id":"B","text":"Stabilizarea mandibulei în relație centrică (RC)."},{"id":"C","text":"Solicitarea excesivă a articulației temporo-mandibulare (ATM)."},{"id":"D","text":"Epuizarea parodonțiului dintelui implicat."},{"id":"E","text":"Supraîncărcarea dintelui cauzal."}],"correct":["C","D","E"],"pages":[244],"source":"set-2"},{"id":"set2-uX5I56Pq","fingerprint":"aa64793f6009c514","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care dintre următoarele afirmații despre Relația Centrică (RC) este corectă în contextul unui pacient edentat parțial întins?","options":[{"id":"A","text":"Este întotdeauna stabilă, deoarece reperele dentare rămase ghidează mandibula."},{"id":"B","text":"Este indusă exclusiv prin metoda Ramfjord."},{"id":"C","text":"Poate fi determinată cu ajutorul machetelor de ocluzie."},{"id":"D","text":"Este considerată normală indiferent de rapoartele de ocluzie."},{"id":"E","text":"Coincide întotdeauna cu intercuspidarea maximă (IM)."}],"correct":["C"],"pages":[244],"source":"set-2"},{"id":"set2-yIO3u6Qs","fingerprint":"241bfbe8432cff64","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Pe traiectoria de închidere posturală mandibulară, ce segment este parcurs în cazul unui 'Long Centric'?","options":[{"id":"A","text":"De la Intercuspidarea Maximă (IM) la Relația Centrică (RC)."},{"id":"B","text":"De la Relația de Postură (RP) la Relația Centrică (RC)."},{"id":"C","text":"De la Relația de Postură (RP) la Intercuspidarea Maximă (IM)."},{"id":"D","text":"Exclusiv pe panta retroincisivă."},{"id":"E","text":"De la Relația Centrică (RC) la Relația de Postură (RP)."}],"correct":["C"],"pages":[244],"source":"set-2"},{"id":"set2--QNqAgzp","fingerprint":"300577f93843a562","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele sunt considerate mișcări și poziții test ce necesită a fi verificate și înregistrate în analiza ocluzală?","options":[{"id":"A","text":"Mișcarea din Intercuspidarea Maximă (IM) în Relație Centrică (RC)."},{"id":"B","text":"Persistența deglutiției infantile."},{"id":"C","text":"Mișcările de lateralitate dreaptă și stângă."},{"id":"D","text":"Mișcările de deschidere și închidere fără contact dentar."},{"id":"E","text":"Masticația unilaterală."}],"correct":["A","C","D"],"pages":[244],"source":"set-2"},{"id":"set2-b4bIR2tz","fingerprint":"8aa6443140276400","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce reprezintă ocluzia terminală centrică?","options":[{"id":"A","text":"O relație mandibulo-craniană dinamică pe traiectoria de la Relația de Postură (RP) la Intercuspidarea Maximă (IM)."},{"id":"B","text":"O poziție mandibulară indusă prin metode precum Dawson sau Ramfjord."},{"id":"C","text":"Momentul în care se produce dezocluzia dinților laterali în protruzie."},{"id":"D","text":"Trecerea de la o relație mandibulo-craniană dinamică de închidere fără contact ocluzal la o relație mandibulară cu contact ocluzal."},{"id":"E","text":"Un contact ocluzal patologic pe partea inactivă în timpul mișcărilor de lateralitate."}],"correct":["D"],"pages":[244],"source":"set-2"},{"id":"set2-nRp3BdY1","fingerprint":"43f8e55d30d908a4","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele modificări pot fi evidențiate în cadrul examinării deglutiției la un pacient cu edentație parțială întinsă?","options":[{"id":"A","text":"Scăderea efortului lingual datorită unui calaj ocluzal optim."},{"id":"B","text":"Traumatizarea excesivă articulară în absența tamponului ocluzal."},{"id":"C","text":"Persistența deglutiției infantile."},{"id":"D","text":"Afectarea funcției fizionomice, indiferent de localizarea edentației."},{"id":"E","text":"Efectuarea unui efort lingual sporit datorită absenței unui calaj ocluzal optim."}],"correct":["B","C","E"],"pages":[245],"source":"set-2"},{"id":"set2-sONDMFXf","fingerprint":"aac0fd47569652e7","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Pentru evaluarea gradului de igienă a cavității orale, care dintre următoarele fețe dentare sunt vizate în mod specific pentru cuantificarea plăcii bacteriene?","options":[{"id":"A","text":"Fața vestibulară a dintelui 4.1."},{"id":"B","text":"Fața vestibulară a dintelui 1.2."},{"id":"C","text":"Fața orală a dintelui 2.1."},{"id":"D","text":"Fața orală a dintelui 3.6."},{"id":"E","text":"Fața vestibulară a dintelui 1.6."}],"correct":["B","D","E"],"pages":[245],"source":"set-2"},{"id":"set2-1R5nocDt","fingerprint":"11386feed730a4a2","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele examene complementare pot fi realizate în cabinetul stomatologic pentru evaluarea stării generale a unui pacient?","options":[{"id":"A","text":"Măsurarea tensiunii arteriale."},{"id":"B","text":"Eliberarea buletinelor de analiză hematologice."},{"id":"C","text":"Examenul citologic exfoliativ."},{"id":"D","text":"Testul la vitamina C."},{"id":"E","text":"Determinarea nivelului de glucoză în sânge."}],"correct":["A","D","E"],"pages":[245],"source":"set-2"},{"id":"set2-M80SpF4z","fingerprint":"5d00892f94d76a84","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"În ce situații se stabilește indicația efectuării examenelor paraclinice locale și loco-regionale la pacientul tânăr edentat parțial?","options":[{"id":"A","text":"În funcție de complexitatea cazului, gradul de disfuncționalitate a ADM și complicațiile care însoțesc edentația."},{"id":"B","text":"Numai pentru investigarea componentelor muco-osoase și a ocluziei dentare."},{"id":"C","text":"În toate cazurile de edentație parțială, indiferent de complexitate."},{"id":"D","text":"Exclusiv atunci când se suspectează o alergie la materialele protetice."},{"id":"E","text":"Doar în cazul prezenței afecțiunilor sistemice cu manifestări orale."}],"correct":["A"],"pages":[245],"source":"set-2"},{"id":"set2-yKSoAN4F","fingerprint":"4259486385004d8e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele metode de investigație sunt utilizate pentru examinarea paraclinică a mucoasei orale?","options":[{"id":"A","text":"Studiul de model."},{"id":"B","text":"Colorațiile intravitale."},{"id":"C","text":"Examenul stomatoscopic."},{"id":"D","text":"Investigațiile imagistice."},{"id":"E","text":"Examenul citologic (citologia exfoliativă)."}],"correct":["B","C","E"],"pages":[245],"source":"set-2"},{"id":"set2-iKVFDKGJ","fingerprint":"df925d6ee29d7f6d","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce informații oferă și ce analize permite studiul de model ca examen complementar în protetica dentară?","options":[{"id":"A","text":"Este un examen imagistic utilizat pentru a investiga unitățile dento-parodontale."},{"id":"B","text":"Permite vizualizarea zonelor greu accesibile clinic și aprecierea elementelor câmpului protetic, modelele fiind examinate separat, în ocluzie și montate în simulator."},{"id":"C","text":"Permite doar vizualizarea zonelor accesibile examenului clinic direct."},{"id":"D","text":"Oferă exclusiv informații despre dinamica mandibulară și relațiile mandibulo-craniene."},{"id":"E","text":"Se utilizează numai pentru analiza echilibrului forțelor active și de rezistență în fazele preprotetice."}],"correct":["B"],"pages":[245],"source":"set-2"},{"id":"set2-MmPGtZhP","fingerprint":"6da2f943b1012d58","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afirmații referitoare la studiul de model sunt corecte?","options":[{"id":"A","text":"Permite o analiză mai riguroasă a spațiului protetic potențial (SPP) decât examenul cavității orale."},{"id":"B","text":"Pentru protezele mobile, se analizează echilibrul forțelor prin diagrame statice și dinamice."},{"id":"C","text":"Analiza la paralelograf este indicată specific în cazul planificării unei proteze parțiale acrilice simple."},{"id":"D","text":"Modelele trebuie examinate separat, în ocluzie și montate într-un simulator."},{"id":"E","text":"În absența molarilor de minte, se examinează cu atenție doar volumul tuberozităților maxilare."}],"correct":["A","B","D"],"pages":[246],"source":"set-2"},{"id":"set2-F0fJxR8n","fingerprint":"8ed7ccc75435bc40","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care este metoda recomandată pentru analiza ocluziei statice în cadrul studiului de model?","options":[{"id":"A","text":"Utilizarea exclusivă a paralelografului pentru a determina axa de inserție și retenția."},{"id":"B","text":"Evaluarea prin teste de mișcare mandibulară precum deschiderea, închiderea și lateralitatea."},{"id":"C","text":"Realizarea de fotografii intraorale în intercuspidare maximă și relație centrică."},{"id":"D","text":"Montarea modelelor în simulator și aprecierea rapoartelor în cele 3 planuri, conform reperelor ocluzale Angle."},{"id":"E","text":"Examinarea directă a modelelor ținute în mână pentru a evalua contactele dentare."}],"correct":["D"],"pages":[246],"source":"set-2"},{"id":"set2-eGyUN2Al","fingerprint":"39bf8f804021846e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele metode fac parte din examenul radiografic utilizat în medicina dentară?","options":[{"id":"A","text":"Radiografia retro-dento-alveolară"},{"id":"B","text":"Radiografia panoramică"},{"id":"C","text":"Scintigrafia osoasă"},{"id":"D","text":"Radiografia cefalometrică"},{"id":"E","text":"Tomodensitometria"}],"correct":["A","B","D"],"pages":[246],"source":"set-2"},{"id":"set2-VmRMBCV5","fingerprint":"beaaa407aa7d76e3","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce metode de investigație paraclinică pot fi utilizate pentru examinarea articulației temporo-mandibulare (ATM)?","options":[{"id":"A","text":"Analiza T-Scan"},{"id":"B","text":"Rezonanța magnetică nucleară"},{"id":"C","text":"Artroscopia cu fibră optică"},{"id":"D","text":"Tomografia"},{"id":"E","text":"Electromiografia (EMG)"}],"correct":["B","C","D"],"pages":[246],"source":"set-2"},{"id":"set2-b24Iodgc","fingerprint":"53b3d64f803095d6","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce presupune mandibulokineziografia?","options":[{"id":"A","text":"O tehnică radiografică specială pentru vizualizarea articulației temporo-mandibulare în mișcare."},{"id":"B","text":"Examinarea relațiilor mandibulo-craniene cu ajutorul arcurilor faciale și articulatoarelor."},{"id":"C","text":"Analiza ocluziei dentare prin examenul gnatosonic și gnatofonic."},{"id":"D","text":"O înregistrare tridimensională a dinamicii mandibulare prin teste de mișcare și investigarea funcțiilor."},{"id":"E","text":"O metodă de investigare a compartimentului muscular prin tonometrie și electromiografie."}],"correct":["D"],"pages":[246],"source":"set-2"},{"id":"set2-qrhAN2rJ","fingerprint":"dc908b0467a2c78f","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt componentele examenului gnatofotostatic?","options":[{"id":"A","text":"Fotografii intraorale în intercuspidare maximă (IM) și relație centrică (RC)."},{"id":"B","text":"Radiografii panoramice și cefalometrice."},{"id":"C","text":"Montarea modelelor într-un simulator mecanic."},{"id":"D","text":"Înregistrarea diagramei Posselt."},{"id":"E","text":"Fotografii extraorale de față și profil."}],"correct":["A","E"],"pages":[246],"source":"set-2"},{"id":"set2-SmHnYngQ","fingerprint":"a63a1ba9f5a0b597","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Prin ce metode poate fi investigat paraclinic compartimentul muscular?","options":[{"id":"A","text":"Tonometrie și electromiografie (EMG)."},{"id":"B","text":"Mandibulokineziografie și înregistrarea diagramei Posselt."},{"id":"C","text":"Tomografie și artrografie temporo-mandibulară."},{"id":"D","text":"Utilizarea articulatoarelor semiadaptabile și a arcurilor faciale."},{"id":"E","text":"Examen gnatosonic și analiză T-Scan."}],"correct":["A"],"pages":[246],"source":"set-2"},{"id":"set2-LFjCmW2R","fingerprint":"67b24375ede194e5","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care este semnificația clinică a liniilor perpendiculare trasate din unghiurile interne ale ochilor în analiza facială din normă frontală?","options":[{"id":"A","text":"Indică mărimea minimă a fantei labiale."},{"id":"B","text":"Determinā poziția șanțului labio-mentonier."},{"id":"C","text":"Sunt folosite pentru a trasa planul Simon."},{"id":"D","text":"Stabilesc lățimea feței la nivelul comisurilor."},{"id":"E","text":"Definesc limita superioară a etajului inferior al feței."}],"correct":["A"],"pages":[247],"source":"set-2"},{"id":"set2-Q7WWNBjH","fingerprint":"e9d8033980a8d342","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afirmații referitoare la proporțiile etajului inferior al feței sunt adevărate?","options":[{"id":"A","text":"Buza inferioară este de două ori mai înaltă decât buza superioară."},{"id":"B","text":"Fanta labială are o lățime egală cu jumătate din lățimea feței la acel nivel."},{"id":"C","text":"Fanta labială se situează la unirea treimii superioare cu cele două treimi inferioare ale etajului."},{"id":"D","text":"Șanțul labio-mentonier se află la jumătatea distanței dintre fanta labială și Gnathion."},{"id":"E","text":"Buza superioară reprezintă 1/3 din distanța Sn-Gn."}],"correct":["C","D","E"],"pages":[247],"source":"set-2"},{"id":"set2-BnOVSnI-","fingerprint":"e7779a3f9af71772","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Ce definește planul Simon utilizat în analiza fotografiei de profil?","options":[{"id":"A","text":"O linie care unește spina nazală anterioară cu porion și trece prin marginea inferioară a buzei superioare."},{"id":"B","text":"O perpendiculară pe planul Frankfurt ce trece prin punctul suborbitar, canin, comisură și gnation."},{"id":"C","text":"O linie ce unește punctele nasion și subnazale, tangentă la gură."},{"id":"D","text":"Unghiul format de tangentele la frunte și la piramida nazală."},{"id":"E","text":"Unghiul dintre filtrul buzei superioare și cloazonul nazal."}],"correct":["B"],"pages":[247],"source":"set-2"},{"id":"set2-S-uACzdv","fingerprint":"0cbd91117b4f5589","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care este intervalul de normalitate pentru unghiul format între filtrul buzei superioare și cloazonul nazal?","options":[{"id":"A","text":"110-120°"},{"id":"B","text":"80-90°"},{"id":"C","text":"90-110°"},{"id":"D","text":"120-140°"},{"id":"E","text":"60-80°"}],"correct":["C"],"pages":[247],"source":"set-2"},{"id":"set2-NyZVm9_c","fingerprint":"a51d54c2540da3a2","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care este succesiunea corectă a tipurilor de diagnostic stabilite pe parcursul tratamentului unui pacient?","options":[{"id":"A","text":"Diagnostic inițial, diagnostic de etapă, diagnostic de urgență, diagnostic final."},{"id":"B","text":"Diagnostic loco-regional, diagnostic de urgență, diagnostic inițial, diagnostic final."},{"id":"C","text":"Diagnostic de etapă, diagnostic final, diagnostic de urgență, diagnostic inițial."},{"id":"D","text":"Diagnostic de urgență, diagnostic inițial, diagnostic de etapă, diagnostic final."},{"id":"E","text":"Diagnostic de urgență, diagnostic de etapă, diagnostic inițial, diagnostic final."}],"correct":["D"],"pages":[247],"source":"set-2"},{"id":"set2-XJ8r_C2q","fingerprint":"27bf02a8d36544e6","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce implicații prezintă vârsta, sexul și profesia în examinarea clinică a pacienților edentați parțial?","options":[{"id":"A","text":"Domiciliul pacientului condiționează în principal alegerea materialelor de amprentă."},{"id":"B","text":"La femei, exigențele estetice sunt mai ridicate, în timp ce la bărbați funcționalitatea este primordială."},{"id":"C","text":"Vârsta pacientului se reflectă asupra terenului, influențând patologia stomatologică și generală geriatrică."},{"id":"D","text":"La bărbați, exigențele estetice sunt considerate prioritare în defavoarea funcționalității."},{"id":"E","text":"Profesia indică anumiți factori etiologici, precum expunerea la noxe, fiind uneori definitorie în alegerea soluției terapeutice."}],"correct":["B","C","E"],"pages":[233],"source":"set-2"},{"id":"set2-8TADlOc0","fingerprint":"db4fc609133d3728","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele aspecte constituie motive de prezentare la medic a pacientului edentat parțial?","options":[{"id":"A","text":"Investigarea antecedentelor heredocolaterale și personale."},{"id":"B","text":"Reoptimizarea unor restaurări protetice vechi, necorespunzătoare din punct de vedere morfo-funcțional."},{"id":"C","text":"Tulburări articulare, musculare și leziuni ale mucoasei."},{"id":"D","text":"Culegerea datelor privitoare la condițiile de viață și muncă."},{"id":"E","text":"Tulburări de diverse grade generate de disfuncțiile masticatorii, fizionomice și fonetice."}],"correct":["B","C","E"],"pages":[234],"source":"set-2"},{"id":"set2-OFTMQZTC","fingerprint":"337d22618f469abe","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele informații sunt obținute prin investigarea istoricului afecțiunii în cadrul anamnezei pacientului edentat parțial?","options":[{"id":"A","text":"Antecedentele generale și stomatologice preexistente."},{"id":"B","text":"Momentul realizării unei protezări mobile anterioare și receptarea acesteia."},{"id":"C","text":"Datele privitoare la condițiile de viață și de muncă."},{"id":"D","text":"Tratamentele urmate anterior și timpul scurs de la pierderea ultimilor dinți."},{"id":"E","text":"Debutul evoluției edentației."}],"correct":["B","D","E"],"pages":[234],"source":"set-2"},{"id":"set2-XWb-duAH","fingerprint":"2219da2f935308d8","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care dintre următoarele elemente culese din istoricul afecțiunii se corelează direct cu morfologia câmpului protetic?","options":[{"id":"A","text":"Timpul scurs de la pierderea ultimilor dinți și tipul tratamentelor urmate."},{"id":"B","text":"Afecțiunile cronice investigate în antecedentele personale generale."},{"id":"C","text":"Momentul realizării unei protezări mobile și receptarea psihologică a acesteia."},{"id":"D","text":"Debutul evoluției edentației și gradul de colaborare cu medicul dentist."},{"id":"E","text":"Cronologia extracțiilor dentare și etiologia pierderii dinților."}],"correct":["E"],"pages":[234],"source":"set-2"},{"id":"set2-38RlVUT6","fingerprint":"9284895da82337e3","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"În contextul obținerii datelor personale, ce informații relevante furnizează evaluarea profesiei pacientului edentat parțial?","options":[{"id":"A","text":"Reprezintă indicatorul principal pentru evaluarea receptării funcționale a unei proteze."},{"id":"B","text":"Condiționează în mod exclusiv nevoia unei reoptimizări a restaurărilor protetice vechi."},{"id":"C","text":"Oferă indicații asupra factorilor etiologici, evidențiind expunerea la medii cu noxe, precum acizii sau plumbul."},{"id":"D","text":"Condiționează în mod direct etapizarea planului de tratament."},{"id":"E","text":"Reprezintă criteriul definitoriu în stabilirea materialului pentru amprenta preliminară."}],"correct":["C"],"pages":[233],"source":"set-2"},{"id":"set2-MIJFDqxq","fingerprint":"212c39f7dc4289b8","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următorii factori se corelează cu antecedentele personale generale (APG) în evaluarea stării biologice a pacientului pentru stabilirea planului de tratament stomatologic?","options":[{"id":"A","text":"Profesia și mediul ocupațional"},{"id":"B","text":"Stările fiziologice"},{"id":"C","text":"Momentul evolutiv biologic"},{"id":"D","text":"Vârsta și sexul pacientului"},{"id":"E","text":"Istoricul extracțiilor dentare"}],"correct":["B","C","D"],"pages":[234],"source":"set-2"},{"id":"set2-RGxpwJi3","fingerprint":"597d9869c3968090","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce factori sau afecțiuni sistemice afectează procesul de resorbție și atrofie sau accentuează atrofia osoasă, generând instabilitatea precoce a soluțiilor terapeutice protetice mobile?","options":[{"id":"A","text":"Terapia iradiantă"},{"id":"B","text":"Terapia cortizonică"},{"id":"C","text":"Profilaxia endocarditei infecțioase"},{"id":"D","text":"Utilizarea acrilatelor flexibile"},{"id":"E","text":"Tulburările metabolice"}],"correct":["A","B","E"],"pages":[235],"source":"set-2"},{"id":"set2-HuRkAAQI","fingerprint":"b992536ef1a5e599","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele măsuri constituie precauții terapeutice esențiale în abordarea stomatologică a pacienților cu afecțiuni generale ce interferă cu patologia orală?","options":[{"id":"A","text":"Aplicarea antibioterapiei de protecție conform protocoalelor pentru bacteremii tranzitorii"},{"id":"B","text":"Evitarea manoperelor dureroase"},{"id":"C","text":"Temporizarea manoperelor stomatologice până la stadiul de compensare a bolii generale"},{"id":"D","text":"Utilizarea de rutină a soluțiilor anestezice cu concentrații ridicate de vasoconstrictor pentru hemostază"},{"id":"E","text":"Inițierea imediată a terapiei protetice independent de diagnosticul afecțiunii generale"}],"correct":["A","B","C"],"pages":[235],"source":"set-2"},{"id":"set2-ExhFS7lY","fingerprint":"63bf4b083145b20f","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"În cazul realizării unei variante terapeutice mobile la pacienții care prezintă o alergie confirmată la acrilate, care este conduita specifică indicată pentru înlocuirea bazei protetice?","options":[{"id":"A","text":"Administrarea continuă a unei medicații antihistaminice pe durata purtării protezei"},{"id":"B","text":"Acoperirea suprafețelor acrilice clasice cu lacuri protectoare izolante"},{"id":"C","text":"Utilizarea exclusivă a aliajelor inerte din titan"},{"id":"D","text":"Inserarea de implante dentare urmată de lucrări ceramice"},{"id":"E","text":"Utilizarea acrilatelor flexibile, deoarece sunt materiale monomer-free"}],"correct":["E"],"pages":[235],"source":"set-2"},{"id":"set2-KhQjDHro","fingerprint":"6f04f5245a766457","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele asocieri între categoria sistemică și entitățile clinice specifice sunt descrise drept afecțiuni cu risc în tratamentul stomatologic?","options":[{"id":"A","text":"Afecțiunile sistemului nervos: diabet, obezitate, avitaminoze"},{"id":"B","text":"Afecțiunile aparatului respirator: astm bronșic, emfizem pulmonar, scleroze pulmonare"},{"id":"C","text":"Afecțiunile aparatului digestiv: gastrite, ulcere, hepatite cronice, ciroze hepatice"},{"id":"D","text":"Discrazii sanguine: obstrucții ale căilor aeriene superioare, anemii"},{"id":"E","text":"Afecțiunile cardiovasculare: miocardiopatii, endarterite, hipertensiune arterială"}],"correct":["B","C","E"],"pages":[234],"source":"set-2"},{"id":"set2-kpYQOnit","fingerprint":"5adac76294934c95","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele aspecte se obțin în mod direct prin elaborarea istoricului stomatologic al pacientului (antecedentele personale stomatologice)?","options":[{"id":"A","text":"Identificarea stereotipului de masticație și a preferințelor pentru textura alimentelor."},{"id":"B","text":"Evaluarea bolilor sistemice care afectează ultimele 3 generații ale familiei."},{"id":"C","text":"Depistarea afecțiunilor stomatologice cu transmitere genetică, precum cariile multiple."},{"id":"D","text":"Modul în care pacientul a fost satisfăcut de soluțiile terapeutice stomatologice anterioare."},{"id":"E","text":"Consemnarea eventualelor parafuncții existente și a acuzelor legate de acestea."}],"correct":["D","E"],"pages":[235],"source":"set-2"},{"id":"set2-UfJ-hNmn","fingerprint":"dcf4c9139dfa0bae","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt bolile de ordin general din cadrul antecedentelor heredo-colaterale care prezintă interes pentru medicul dentist în urma anchetellor familiale?","options":[{"id":"A","text":"Anomaliile dento-maxilare și parodontopatiile."},{"id":"B","text":"Bolile mamei din perioada de sarcină."},{"id":"C","text":"Bolile cu caracter familial asociate unor condiții de mediu comun."},{"id":"D","text":"Bolile cu risc de transmitere."},{"id":"E","text":"Afecțiunile din sfera oro-maxilo-facială care au necesitat intervenții chirurgicale în trecut."}],"correct":["B","C","D"],"pages":[235],"source":"set-2"},{"id":"set2-OTN5oMI_","fingerprint":"7ce5b578f4a6ed06","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Câte generații anterioare ale familiei pacientului sunt vizate, de regulă, de anchetele familiale pentru depistarea bolilor sistemice cu impact în medicina dentară?","options":[{"id":"A","text":"Ultima generație."},{"id":"B","text":"Ultimele patru generații."},{"id":"C","text":"Ultimele trei generații."},{"id":"D","text":"Ultimele cinci generații."},{"id":"E","text":"Ultimele două generații."}],"correct":["C"],"pages":[235],"source":"set-2"},{"id":"set2-C5ygopXF","fingerprint":"a2a2315bbdc60b64","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce date trebuie consemnate în cadrul evaluării condițiilor de viață și muncă ale pacientului?","options":[{"id":"A","text":"Momentul protezării și modul în care a decurs acomodarea cu proteza mobilizabilă."},{"id":"B","text":"Preponderența consumului de condimente și tutun."},{"id":"C","text":"Existența unor eventuale ticuri profesionale."},{"id":"D","text":"Stereotipul de masticație."},{"id":"E","text":"Existența malformațiilor congenitale cu transmitere genetică."}],"correct":["B","C","D"],"pages":[235],"source":"set-2"},{"id":"set2-Rjj8yG7S","fingerprint":"a57b4c0a6d998d1b","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele entități patologice se analizează în vederea depistării transmiterii lor genetice prin intermediul antecedentelor heredo-colaterale stomatologice?","options":[{"id":"A","text":"Anomaliile dento-maxilare."},{"id":"B","text":"Parodontopatiile."},{"id":"C","text":"Cariile multiple."},{"id":"D","text":"Bruxismul."},{"id":"E","text":"Malformațiile congenitale oro-faciale."}],"correct":["A","B","C","E"],"pages":[235],"source":"set-2"},{"id":"set2-ImsPy3vU","fingerprint":"d3ca5fa3a17d2f0b","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afirmații referitoare la evaluarea dimensiunii etajului inferior al feței sunt corecte?","options":[{"id":"A","text":"În relația de postură, mărirea etajului inferior este determinată de hipotonii musculare pe mușchii ridicători și hipertonii pe cei coborâtori."},{"id":"B","text":"Diferența normală dintre valoarea etajului inferior în relația de postură și cea în relația centrică este de 2 - 4 mm."},{"id":"C","text":"În relația de postură, micșorarea etajului inferior poate fi cauzată de hipertonii musculare pe mușchii coborâtori."},{"id":"D","text":"Pierderea stopurilor centrice laterale determină o micșorare a etajului inferior exclusiv în relația de postură."},{"id":"E","text":"În relația centrică, mărirea etajului inferior se poate datora anomaliilor dento-maxilare primare cu supra-alveolie și mordex apertus."}],"correct":["A","B","E"],"pages":[237],"source":"set-2"},{"id":"set2-xHGlW7W_","fingerprint":"6c59c170dbf2fdf4","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Referitor la inspecția de profil a feței, care dintre următoarele elemente clinice sunt evaluate și descrise cu valori sau caracteristici specifice?","options":[{"id":"A","text":"Șanțul labio-mentonier este constant din punct de vedere morfologic, indiferent de statusul odontal al zonei frontale."},{"id":"B","text":"Unghiul gonial (UG) înregistrează valori cuprinse între 130-140° la persoanele vârstnice."},{"id":"C","text":"Unghiul nazo-labial are o valoare normală de 90° și nu este influențat de prezența sau absența dinților superiori."},{"id":"D","text":"Treapta labială normală presupune ca buza superioară să acopere sau să depășească ușor conturul buzei inferioare."},{"id":"E","text":"Profilul facial se stabilește în funcție de planurile Simon, Dreyfus și Frankfurt, putând fi concav, drept sau convex."}],"correct":["B","D","E"],"pages":[237],"source":"set-2"},{"id":"set2-mde5P0VT","fingerprint":"bc7d462340de5c2d","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele asimetrii decelabile la inspecția facială de față sunt asociate corect cu cauzele lor etiopatogenice?","options":[{"id":"A","text":"Asimetriile de cauză ocluzală sunt generate exclusiv de anomaliile dento-alveolare primare."},{"id":"B","text":"Asimetriile de cauză articulară se pot manifesta prin deformarea zonei pretragiene în cadrul poliartritelor reumatoide."},{"id":"C","text":"Asimetriile de cauză musculară pot fi rezultatul unor hipertrofii, spasme musculare sau hipertonii."},{"id":"D","text":"Asimetriile de cauză osoasă pot fi reprezentate de exostoze, dismorfisme sau consolidări osoase vicioase."},{"id":"E","text":"Malrelațiile mandibulo-craniene determină asimetrii faciale prin laterodeviația consecutivă a maxilarului."}],"correct":["B","C","D"],"pages":[237],"source":"set-2"},{"id":"set2-tDXUR0qw","fingerprint":"245b85113099352b","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care este cauza care determină micșorarea etajului inferior al feței în relația centrică (RC)?","options":[{"id":"A","text":"Hipotoniile musculare pe mușchii coborâtori ai mandibulei."},{"id":"B","text":"Refacerile protetice defectuoase localizate în zonele laterale."},{"id":"C","text":"Existența unor anomalii dento-maxilare primare cu supra-alveolie și mordex apertus."},{"id":"D","text":"Spasmele sau hipertoniile musculare pe mușchii ridicători."},{"id":"E","text":"Infraalveoliile zonei laterale cu ocluzie adâncă și pierderea stopurilor centrice laterale."}],"correct":["E"],"pages":[236,237],"source":"set-2"},{"id":"set2-eGeopG_l","fingerprint":"9056b226e6401d4f","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele manevre și obiective sunt asociate corect cu tehnicile de palpare din cadrul examenului cervico-facial?","options":[{"id":"A","text":"Temperatura scăzută a tegumentelor însoțită de transpirații reci indică o leziune inflamatorie locală severă."},{"id":"B","text":"Palparea mușchilor se realizează doar extraoral, static și dinamic, pentru a evalua tonicitatea și puterea de contracție."},{"id":"C","text":"Manevrele Netter presupun opunerea rezistenței la mișcările de deschidere, închidere, propulsie și diducție, testând mușchii dinamic."},{"id":"D","text":"Elasticitatea și cantitatea țesutului subcutanat se evidențiază în cadrul palpării superficiale prin pensare."},{"id":"E","text":"Aprecierea sensibilității termice se realizează în cadrul palpării superficiale utilizând eprubete cu apă rece."}],"correct":["C","D","E"],"pages":[237],"source":"set-2"},{"id":"set2-9MEaIgj1","fingerprint":"15a81b76f0bebb7a","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care este reperul anatomic exact pentru palparea regiunii pretragiene în cadrul examenului articulației temporo-mandibulare?","options":[{"id":"A","text":"La 13 mm anterior de tragus, pe linia ce unește comisura labială cu tragusul."},{"id":"B","text":"La 13 mm anterior de tragus, pe linia ce unește unghiul extern al ochiului cu tragusul."},{"id":"C","text":"La 13 mm anterior de tragus, pe linia ce unește unghiul intern al ochiului cu tragusul."},{"id":"D","text":"Pe o linie oblică situată la 13 mm inferior de conductul auditiv extern."},{"id":"E","text":"La 15 mm anterior de tragus, paralel cu marginea inferioară a arcadei zigomatice."}],"correct":["B"],"pages":[238],"source":"set-2"},{"id":"set2-jPWS_O-7","fingerprint":"30146930eaf2c918","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt afirmațiile medicale valabile privind palparea în dinamică a articulației temporo-mandibulare?","options":[{"id":"A","text":"Palparea cu cele patru degete poziționate pretragian permite aprecierea excursiilor condiliene."},{"id":"B","text":"Traiectoria de rotație pură condiliană se evaluează exclusiv prin palparea cu patru degete pretragian."},{"id":"C","text":"Evaluarea traiectoriei de rotație pură condiliană reprezintă unul dintre obiectivele palpării bidigitale."},{"id":"D","text":"Metoda bidigitală implică poziționarea indexurilor intraoral, la nivelul mucoasei jugale."},{"id":"E","text":"Palparea bidigitală se realizează prin poziționarea indexurilor în canalele auditive externe."}],"correct":["A","C","E"],"pages":[238],"source":"set-2"},{"id":"set2-N9YWxCY3","fingerprint":"4905c7a72ecbd668","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Prin ce manevră clinică se decelează sensibilitatea elementelor articulare la nivelul articulației temporo-mandibulare?","options":[{"id":"A","text":"Percutând blând regiunea pretragiană bilateral în timpul deglutiției."},{"id":"B","text":"Executând presiuni pe unghiul mandibular în sens postero-superior, în ocluzie centrică."},{"id":"C","text":"Solicitând pacientului să execute mișcări de lateralitate extremă contra unei rezistențe aplicate pe menton."},{"id":"D","text":"Executând presiuni pe menton în sens postero-superior, în timp ce bolnavul are gura întredeschisă."},{"id":"E","text":"Executând presiuni pe menton în sens antero-inferior, cu gura larg deschisă."}],"correct":["D"],"pages":[238],"source":"set-2"},{"id":"set2-wAuZzUwj","fingerprint":"ad697f710b277b0c","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce elemente clinice sunt urmărite în timpul inspecției dinamice a articulației temporo-mandibulare la deschiderea și închiderea gurii?","options":[{"id":"A","text":"Amplitudinea deschiderii gurii."},{"id":"B","text":"Traiectoria de mișcare a mentonului evaluată din profil."},{"id":"C","text":"Simetria excursiilor mentonului față de planul medio-sagital observată din față."},{"id":"D","text":"Decelarea prezenței cracmentelor sau crepitațiilor articulare concomitente."},{"id":"E","text":"Modificările de culoare și integritatea tegumentară din regiunea pretragiană și mentonieră."}],"correct":["A","B","C"],"pages":[238],"source":"set-2"},{"id":"set2-WNRkxsaG","fingerprint":"9161f4213dab7021","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt elementele evaluate în cadrul examinării statice a orificiului cavității orale?","options":[{"id":"A","text":"Tonicitatea musculaturii periorale"},{"id":"B","text":"Culoarea și textura labială"},{"id":"C","text":"Raportul bilabial sau treapta labială"},{"id":"D","text":"Amplitudinea maximă a deschiderii cavității orale"},{"id":"E","text":"Simetria arcului Cupidon"}],"correct":["B","C","E"],"pages":[238],"source":"set-2"},{"id":"set2-q7kzkyYS","fingerprint":"77c3dd7a04813a39","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Cum influențează factorul socio-economic decizia terapeutică în practica clinică dentară?","options":[{"id":"A","text":"Favorizează alegerea tratamentelor conservatoare prin reducerea costurilor pe termen lung"},{"id":"B","text":"Crește acceptabilitatea tratamentelor complexe, cu numeroase etape clinice"},{"id":"C","text":"Exclude motivele financiare din planificarea protetică, punând accent pe profilaxie"},{"id":"D","text":"Orientează decizia terapeutică spre extracție dentară în defavoarea tratamentelor conservatoare"},{"id":"E","text":"Impune necesitatea unui număr crescut de ședințe de tratament pentru reabilitarea orală"}],"correct":["D"],"pages":[228],"source":"set-2"},{"id":"set2-x8NOOcog","fingerprint":"a7c5eaeb7b18f7bb","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt structurile și parametrii evaluați în mod sistematic, în ordine, în timpul examenului clinic al cavității orale?","options":[{"id":"A","text":"Palatul dur și moale, limba și planșeul"},{"id":"B","text":"Orificiul cavității orale, mucoasa jugală și vestibulul cavității orale"},{"id":"C","text":"Profilul facial și simetria facială de ansamblu"},{"id":"D","text":"Tensiunea arterială și frecvența respiratorie"},{"id":"E","text":"Suportul odontal, SPP și suportul parodontal"}],"correct":["A","B","E"],"pages":[238],"source":"set-2"},{"id":"set2-3aQUePey","fingerprint":"efb849686d8bd4f8","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care dintre următoarele reprezintă complicații locale într-un prim timp ale edentației parțiale întinse, distincte de complicațiile loco-regionale atrase în cascadă?","options":[{"id":"A","text":"Subdimensionarea etajului inferior"},{"id":"B","text":"Disfuncțiile cranio-mandibulare"},{"id":"C","text":"Migrările în plan orizontal și vertical"},{"id":"D","text":"Anchiloza articulației temporo-mandibulare"},{"id":"E","text":"Malocluziile"}],"correct":["C"],"pages":[238],"source":"set-2"},{"id":"set2-cFYRyqfU","fingerprint":"42ba7d45fb67d9bf","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele substanțe au rol algogenic și sunt implicate în stimularea nocivă a nociceptorilor periferici în cadrul fenomenului de durere acută?","options":[{"id":"A","text":"Endorfina"},{"id":"B","text":"Bradikinina"},{"id":"C","text":"Acetilcolina"},{"id":"D","text":"Substanța P"},{"id":"E","text":"Histamina"}],"correct":["B","D","E"],"pages":[238],"source":"set-2"},{"id":"set2-qXZ5ZLKS","fingerprint":"b67dbff16a50044c","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt criteriile de diagnostic temporal și caracteristicile clinice ale durerii cronice?","options":[{"id":"A","text":"Limitarea transmiterii impulsurilor dureroase la nivelul cornului ventral medular"},{"id":"B","text":"Persistența sau repetarea simptomatologiei pentru mai mult de 3 luni"},{"id":"C","text":"Persistența simptomatologiei mai mult de o lună după amendarea unei injurii tisulare acute"},{"id":"D","text":"Asocierea cu o leziune care nu prezintă tendință la vindecare"},{"id":"E","text":"Apariția durerii exclusiv în prezența unor leziuni tisulare manifeste"}],"correct":["B","C","D"],"pages":[238],"source":"set-2"},{"id":"set2-d8r5DPh5","fingerprint":"f0f1dceb35c5e37f","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afirmații descriu corect manifestările clinice faciale ce pot apărea în edentația parțială întinsă și anomaliile dentare asociate?","options":[{"id":"A","text":"Ectopiile de canin pot determina asimetria arcului Cupidon și a buzei"},{"id":"B","text":"Edentațiile frontale paramediene sunt incriminate în apariția asimetriei arcului Cupidon"},{"id":"C","text":"Subdimensionarea etajului inferior servește drept marker al dezechilibrelor ocluzo-articulare"},{"id":"D","text":"Absența mai multor dinți frontali succesivi se asociază la inspecție cu înfundarea buzei și mărirea roșului buzei"},{"id":"E","text":"Înfundarea obrajilor reprezintă o consecință exclusivă a laxității capsulo-ligamentare"}],"correct":["A","B","C"],"pages":[239],"source":"set-2"},{"id":"set2-rISl2_q5","fingerprint":"11ad8502426897f5","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele condiții patologice sunt menționate drept cauze ale micșorării amplitudinii deschiderii cavității orale?","options":[{"id":"A","text":"Laxitatea capsulo-ligamentară la nivelul articulației temporo-mandibulare"},{"id":"B","text":"Trismusul mușchiului maseter"},{"id":"C","text":"Microstomia"},{"id":"D","text":"Anchiloza articulației temporo-mandibulare"},{"id":"E","text":"Fracturile condiliene"}],"correct":["B","C","D","E"],"pages":[239],"source":"set-2"},{"id":"set2-3crtU-7r","fingerprint":"eb8fc745b5dd4ee7","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt situațiile în care simetria deschiderii orificiului cavității orale poate fi afectată prin devierea mentonului?","options":[{"id":"A","text":"Afecțiuni care interesează articulația temporo-mandibulară"},{"id":"B","text":"Edentații parțiale intercalate, aparținând clasei a III-a Kennedy"},{"id":"C","text":"Edentații parțiale uniterminale"},{"id":"D","text":"Anchiloze dento-alveolare generalizate"},{"id":"E","text":"Paralizii și pareze faciale"}],"correct":["A","C","E"],"pages":[239],"source":"set-2"},{"id":"set2-zww-B3zI","fingerprint":"055157947b681c06","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce elemente se evaluează în cadrul examinării de ansamblu a mucoasei labio-jugale?","options":[{"id":"A","text":"Examinarea zonelor funcționale din punct de vedere al suportului muco-osos"},{"id":"B","text":"Prolabarea mucoasei spre spațiul edentat ca urmare a ticurilor de succiune"},{"id":"C","text":"Inserția frenurilor și a plicilor alveolo-jugale în raport cu festonul gingival"},{"id":"D","text":"Prezența amprentei dinților și a interliniului articular"},{"id":"E","text":"Prezența corpusculilor Fordyce în zonele învecinate canalului Stenon"}],"correct":["B","D","E"],"pages":[239],"source":"set-2"},{"id":"set2-I9uqk4k_","fingerprint":"f2f73adb6b62fb14","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care este diferența principală în ceea ce privește zonele funcționale periferice între edentația totală și edentația parțială întinsă?","options":[{"id":"A","text":"În edentația parțială întinsă se descriu întotdeauna toate zonele funcționale într-o ordine clară, neîntreruptă de dinții restanți."},{"id":"B","text":"Zonele funcționale periferice din edentația parțială întinsă nu prezintă limitări anatomice clare comparativ cu cele din edentația totală."},{"id":"C","text":"În edentația totală zonele funcționale se succed într-o ordine clară, în timp ce în edentația parțială întinsă se întâlnesc una sau două zone, deseori scurtate sau întrerupte."},{"id":"D","text":"În edentația totală zonele funcționale sunt evaluate static de la dreapta la stânga, în timp ce în edentația parțială întinsă se examinează doar dinamic."},{"id":"E","text":"Examinarea suportului muco-osos se realizează exclusiv în edentația totală, fiind omisă în edentația parțială întinsă datorită prezenței dinților stâlpi."}],"correct":["C"],"pages":[239],"source":"set-2"},{"id":"set2-ZueQpjIF","fingerprint":"6e790a9d4125b27c","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt caracteristicile examinării zonelor periferice vestibulare?","options":[{"id":"A","text":"Parcurgerea zonelor se efectuează de la dreapta la stânga."},{"id":"B","text":"Examinarea se efectuează de la stânga la dreapta pentru a evidenția inserția corectă a frenurilor."},{"id":"C","text":"Examinarea trebuie să includă strict mobilizarea dinamică a țesuturilor de la periferia câmpului protetic."},{"id":"D","text":"Examinarea se realizează prin inspecție și palpare."},{"id":"E","text":"Examinarea se face atât static, cât și dinamic."}],"correct":["A","D","E"],"pages":[239],"source":"set-2"},{"id":"set2-t3ljSq4s","fingerprint":"97887a55b1fbc790","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce aspecte trebuie consemnate în mod specific la examinarea vestibulului cavității orale?","options":[{"id":"A","text":"Abcese, formațiuni tumorale, fistule și cicatrici"},{"id":"B","text":"Inserția frenurilor în raport cu festonul gingival"},{"id":"C","text":"Amplitudinea spațiului interlabial în timpul surâsului"},{"id":"D","text":"Amprenta interliniului articular"},{"id":"E","text":"Inserția plicilor alveolo-jugale în raport cu festonul gingival"}],"correct":["A","B","E"],"pages":[239],"source":"set-2"},{"id":"set2-AmpGMS_N","fingerprint":"ee2ce4cc636ee93e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care dintre următoarele afirmații descrie o etapă validă în procedura de examinare clinică a pungii Eisenring și a regiunilor învecinate?","options":[{"id":"A","text":"Evaluarea mucoasei pasiv-mobile din zona frontală este facilitată masiv de absența totală a țesutului submucos."},{"id":"B","text":"Zona de mucoasă pasiv-mobilă se analizează doar prin examinare vizuală de la distanță, fiind contraindicată instrumentarea mecanică."},{"id":"C","text":"Aprecierea înălțimii corecte a zonei se obține prin bascularea mandibulei spre zona examinată."},{"id":"D","text":"Aprecierea înălțimii zonei se realizează exclusiv prin bascularea mandibulei de partea opusă regiunii examinate."},{"id":"E","text":"Aprecierea lățimii pungii necesită bascularea mandibulei direct spre zona care face obiectul examinării."}],"correct":["C"],"pages":[239,240,241],"source":"set-2"},{"id":"set2-5l-ot-05","fingerprint":"13ef9c23ee49ecbe","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt elementele definitorii și principiile de examinare specifice zonei palatine „Ah”?","options":[{"id":"A","text":"Palparea la nivel palatinal se realizează manevrând fuloarul dinspre posterior spre anterior și exclusiv de la stânga spre dreapta."},{"id":"B","text":"Testarea dinamică a acestei zone impune punerea în tensiune a vălului palatin prin utilizarea manevrei Valsalva, a tusei ușoare și a emiterii vocalei „A”."},{"id":"C","text":"Atât dimensiunea transversală, cât și valoarea clinică a acestei zone sunt supuse variațiilor generate de incidența vălului palatin."},{"id":"D","text":"Poziția orizontală a vălului palatin reprezintă configurația considerată de maximă favorabilitate pentru obținerea unei succiuni optime."},{"id":"E","text":"Această arie anatomică reprezintă o zonă periferică de închidere marginală, lipsită de un rol mecanic, având strict o funcție fonetică."}],"correct":["B","C"],"pages":[239,240,241],"source":"set-2"},{"id":"set2-JeoCy-yX","fingerprint":"dd6cbec0a2418f6e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce particularități topografice și repere de evaluare clinică sunt asociate zonelor funcționale periferice mandibulare?","options":[{"id":"A","text":"Torusul mandibular poate fi interceptat palpatoriu la nivelul versantului intern al crestei edentate, în dreptul unităților premolare."},{"id":"B","text":"Explorarea zonei linguale laterale oferă indicii palpatorii exclusive despre poziția și tonicitatea mușchiului genioglos."},{"id":"C","text":"Prezența mușchilor a căror inserție are o dispoziție perpendiculară determină modificări clinice marcante la nivelul zonei vestibulare centrale mandibulare."},{"id":"D","text":"Zona vestibulară laterală se află sub incidența directă a inserției mușchiului milohioidian."},{"id":"E","text":"Zona linguală centrală constituie o regiune esențială de închidere marginală, ale cărei caracteristici decurg din inserția mușchiului genioglos."}],"correct":["A","C","E"],"pages":[239,240,241],"source":"set-2"},{"id":"set2-rxlzDQJI","fingerprint":"7f6246cf473bd91c","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care dintre următorii parametri patologici sau fiziologici se evaluează în mod direct prin manoperele de inspecție, palpare și sondaj destinate strict suportului parodontal?","options":[{"id":"A","text":"Gradul de vitalitate a unităților odonto-parodontale restante pe arcadă."},{"id":"B","text":"Simetria de ansamblu și continuitatea arcadelor dento-alveolare la nivel maxilar și mandibular."},{"id":"C","text":"Cuantificarea mobilității dentare și importanța pierderii de atașament parodontal clinic."},{"id":"D","text":"Natura și integritatea tratamentelor odontale efectuate anterior la nivelul coroanelor clinice."},{"id":"E","text":"Morfologia coronară a stâlpilor limitanți și calitatea punctelor de contact proximale."}],"correct":["C"],"pages":[241],"source":"set-2"},{"id":"set2-cFfEmA0w","fingerprint":"bdae75540af4b79b","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt particularitățile topografice, structurale și metodologice asociate examinării zonelor vestibulare și frontale ale câmpului protetic maxilar?","options":[{"id":"A","text":"Trecerea dintre regiunea fixă și mucoasa pasiv-mobilă în zona frontală este ușor identificabilă pe seama prezenței atrofiei tisulare generalizate."},{"id":"B","text":"Din punct de vedere delimitativ, zona frontală se situează constant între cele două plici alveolo-jugale."},{"id":"C","text":"Determinarea lățimii zonei frontale este dictată simultan de imperative fizionomice, de prezența inserției frenului labial și de gradul de retentivitate al versantului vestibular."},{"id":"D","text":"La nivelul zonei vestibulare laterale, o îngroșare a marginilor piesei protetice este absolut contraindicată deoarece generează o instabilitate mecanică imediată."},{"id":"E","text":"Explorarea funcțională a zonei vestibulare laterale drepte impune cu necesitate utilizarea testelor de mimică și a mișcărilor de tracțiune posterioară a buzei superioare."}],"correct":["B","C","E"],"pages":[241],"source":"set-2"},{"id":"set2-Hp-M0rnC","fingerprint":"2c7079078564ada7","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele asocieri între elementul clinic examinat la pacientul edentat și sistemul de clasificare sau indicele utilizat sunt corecte?","options":[{"id":"A","text":"Creasta edentată la pacientul edentat parțial - clasificarea Atwood."},{"id":"B","text":"Suportul osos maxilar - indicii Koller-Russov."},{"id":"C","text":"Fibromucoasa crestei edentate - indicii Lejoyeux."},{"id":"D","text":"Torusul palatin - clasificarea Landa."},{"id":"E","text":"Suportul osos mandibular - indicii Schröder."}],"correct":["A","C","D"],"pages":[241],"source":"set-2"},{"id":"set2-zws_MfUu","fingerprint":"0f5f7b0b85bb20d9","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt afirmațiile adevărate privind examinarea zonelor anatomice de suport la pacienții edentați?","options":[{"id":"A","text":"Tuberculii piriformi și tuberozitățile maxilare constituie zone biostatice care își conservă în general volumul și forma."},{"id":"B","text":"Ligamentul pterigo-mandibular limitează mezial extinderea protezei la nivelul tuberculului piriform."},{"id":"C","text":"Examinarea crestelor edentate maxilare se începe de la tuberozitatea dreaptă spre cea stângă."},{"id":"D","text":"Bolta palatină constituie o zonă secundară de sprijin pentru protezele parțiale mobilizabile."},{"id":"E","text":"Tuberozitățile maxilare reprezintă o zonă biostatică ce se poate hipertrofia, ducând uneori la mărirea spațiului protetic potențial."}],"correct":["A","C"],"pages":[241],"source":"set-2"},{"id":"set2-TQ_TaxmM","fingerprint":"5eb463831669da87","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt parametrii ocluzali a căror analiză și cuantificare se impun obligatoriu pentru stabilirea diagnosticului și planului de tratament la pacientul edentat?","options":[{"id":"A","text":"Curbura frontală."},{"id":"B","text":"Cuspizii de sprijin și cuspizii de ghidaj."},{"id":"C","text":"Curba de ocluzie sagitală Monson și Villain."},{"id":"D","text":"Curba de ocluzie transversală Spee-Balkwill."},{"id":"E","text":"Planul de ocluzie."}],"correct":["A","B","E"],"pages":[243],"source":"set-2"},{"id":"set2-W9wJXh9q","fingerprint":"3c7f53e7cd32f4bc","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Ce caracteristici definesc contactele dento-dentare într-o ocluzie normală ideală?","options":[{"id":"A","text":"Pot avea un tipar funcțional de tip cuspid-fosetă sau cuspid-ambrazură."},{"id":"B","text":"Sunt punctiforme și uniform distribuite pe arcadă, pe toți dinții cuspidați."},{"id":"C","text":"Se realizează exclusiv între suprafețe plane pentru a asigura o stabilitate maximă."},{"id":"D","text":"Sunt unice și localizate exclusiv în zonele laterale de sprijin."},{"id":"E","text":"Se stabilesc predominant sub formă de contact între fața vestibulară și marginea incizală."}],"correct":["A","B"],"pages":[243],"source":"set-2"},{"id":"set2-MlRhW4fc","fingerprint":"25546aaf634e1e6f","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Referitor la examenul planșeului cavității orale și al limbii, care afirmație reflectă conduita clinică și particularitățile anatomice vizate?","options":[{"id":"A","text":"Palparea zonelor planșeului se realizează exclusiv unimanual pentru a asigura o precizie tactilă ridicată."},{"id":"B","text":"Examenul mucoasei linguale se bazează exclusiv pe evaluarea modificărilor de volum, ignorând distribuția zonelor papilare."},{"id":"C","text":"Poziția limbii în repaus se verifică în clinică prin deschiderea ușoară a gurii de către pacient."},{"id":"D","text":"Poziția posterioară a limbii este considerată a fi cea mai favorabilă din punct de vedere protetic."},{"id":"E","text":"Examinarea versantului lingual al arcului anterior mandibular are ca scop principal aprecierea inserției mușchiului milohioidian."}],"correct":["C"],"pages":[242],"source":"set-2"},{"id":"set2-CGsochMj","fingerprint":"c97cdf4b8aba5ffa","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"În cadrul etapei de analiză și înregistrare ocluzală, care sunt termenii asociați corelației posibile dintre intercuspidarea maximă (IM) și relația centrică (RC)?","options":[{"id":"A","text":"Spee-Balkwill, Monson, Villain."},{"id":"B","text":"Cusp-fossa, cusp-embrasure, point-centric."},{"id":"C","text":"T-Scan, banda Joffe, long-centric."},{"id":"D","text":"Point-centric, wide centric, long-centric."},{"id":"E","text":"Angle-centric, wide centric, short-centric."}],"correct":["D"],"pages":[243],"source":"set-2"},{"id":"set2--5tm9M1s","fingerprint":"2ab77450cf55bbf2","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la traiectoriile de închidere mandibulară cu semnificație funcțională?","options":[{"id":"A","text":"Traiectoria de închidere în relație centrică descrie faza finală a mișcării de închidere, mandibula efectuând o mișcare de rotație pură."},{"id":"B","text":"Ocluzia terminală posturală realizează trecerea de la relația mandibulo-craniană dinamică la relația mandibulară cu contact ocluzal exclusiv în relație centrică."},{"id":"C","text":"Traiectoria de închidere posturală mai este denumită și traiectorie musculară."},{"id":"D","text":"Pe traiectoria de închidere posturală, mandibula parcurge segmentul dintre relația posturală și intercuspidarea maximă în cazul unui Long Centric."},{"id":"E","text":"Traiectoria de închidere în relație centrică este denumită impropriu și traiectorie musculară."}],"correct":["A","C","D"],"pages":[243,244],"source":"set-2"},{"id":"set2-cyAJDp0h","fingerprint":"d9e978d294c97209","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele afirmații descriu exact mișcările test și fenomenele de dezocluzie asociate dinamicii mandibulare?","options":[{"id":"A","text":"În protruzia fiziologică se produce dezocluzia în zona frontală, mișcarea fiind ghidată exclusiv de grupul lateral."},{"id":"B","text":"În mișcarea de lateralitate, pe partea inactivă se produce dezocluzia dinților laterali, reprezentând fenomenul Christensen lateral."},{"id":"C","text":"În mișcarea de protruzie, mișcarea este preluată de panta retroincisivă, evidențiindu-se fenomenul Christensen sagital."},{"id":"D","text":"Păstrarea patologică a contactelor pe partea inactivă determină o solicitare excesivă a articulației temporo-mandibulare."},{"id":"E","text":"Mișcările test fără contact dentar includ lateralitatea dreaptă și stângă, precum și protruzia."}],"correct":["B","C","D"],"pages":[243,244],"source":"set-2"},{"id":"set2-NaojNV2F","fingerprint":"29d17edb53b43ff3","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"Care dintre următoarele caracteristici definește ocluzia terminală centrică?","options":[{"id":"A","text":"Reprezintă faza în care mandibula efectuează o mișcare de translație pură pe traiectoria finală."},{"id":"B","text":"Este rezultatul parcurgerii segmentului dintre relația posturală și intercuspidarea maximă."},{"id":"C","text":"Realizează trecerea de la relația mandibulo-craniană dinamică de închidere fără contact ocluzal la relația mandibulară cu contact ocluzal."},{"id":"D","text":"Determină apariția fenomenului Christensen sagital prin preluarea mișcării de către panta retroincisivă."},{"id":"E","text":"Se înregistrează exclusiv în timpul mișcărilor de deschidere și închidere a cavității orale."}],"correct":["C"],"pages":[243,244],"source":"set-2"},{"id":"set2-XR0kKFIw","fingerprint":"0e99726a4b3f9c3b","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CS","text":"În dinamica mandibulară, care afirmație referitoare la traiectoria de închidere posturală este exactă?","options":[{"id":"A","text":"Mandibula parcurge segmentul dintre relația posturală și intercuspidarea maximă în cazul unui Long Centric."},{"id":"B","text":"Este caracterizată prin efectuarea unei mișcări de rotație pură a mandibulei pe toată durata traiectoriei."},{"id":"C","text":"Mandibula parcurge segmentul dintre relația posturală și intercuspidarea maximă în cazul unui Point Centric."},{"id":"D","text":"Ocluzia terminală posturală realizează trecerea de la relația mandibulo-craniană dinamică la relația de ocluzie centrică."},{"id":"E","text":"Mandibula parcurge segmentul reprezentat exclusiv de relația centrică în cazul unui Long Centric."}],"correct":["A"],"pages":[243,244],"source":"set-2"},{"id":"set2-ZK-40T_g","fingerprint":"f4345899eac67b88","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt consecințele patologice ale păstrării contactelor ocluzale pe partea inactivă în timpul mișcării de lateralitate a mandibulei?","options":[{"id":"A","text":"Apariția fenomenului Christensen lateral prin ghidaj pe panta retroincisivă."},{"id":"B","text":"Producerea dezocluziei imediate a dinților laterali de partea activă."},{"id":"C","text":"Epuizarea parodonțiului dintelui cauzal."},{"id":"D","text":"Solicitarea excesivă a articulației temporo-mandibulare."},{"id":"E","text":"Supraîncărcarea mecanică a dintelui cauzal."}],"correct":["C","D","E"],"pages":[243,244],"source":"set-2"},{"id":"set2-_O6bSQpb","fingerprint":"4ed38bf0ab78455a","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele metode pot fi utilizate pentru investigarea paraclinică a mucoasei orale?","options":[{"id":"A","text":"Examenul citologic (citologia exfoliativă)"},{"id":"B","text":"Examenul gnatosonic"},{"id":"C","text":"Artroscopia cu fibră optică"},{"id":"D","text":"Testul la vitamina C"},{"id":"E","text":"Colorațiile intravitale"}],"correct":["A","D","E"],"pages":[245],"source":"set-2"},{"id":"set2-9EoTiExC","fingerprint":"fbe7aeb0337ae38e","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care sunt afirmațiile adevărate privind studiul de model în protetica dentară?","options":[{"id":"A","text":"Studiul de model oferă o analiză a spațiului protetic potențial inferioară celei realizate direct la nivelul cavității orale."},{"id":"B","text":"Tuberozitățile maxilare și tuberculii piriformi mandibulari sunt examinați cu atenție privind volumul, sensul și gradul de retentivitate, mai ales când lipsesc molarii de minte."},{"id":"C","text":"Analiza la paralelograf este recomandată pentru elaborarea tratamentului ce presupune o proteză scheletată."},{"id":"D","text":"Ocluzia statică se analizează în planurile sagital, transversal și vertical, folosind reperele ocluzale ale lui Angle."},{"id":"E","text":"Examinarea modelelor se face exclusiv separat, pentru a aprecia elementele pozitive și negative ale câmpului protetic."}],"correct":["B","C","D"],"pages":[246],"source":"set-2"},{"id":"set2-X9wFL46M","fingerprint":"010e3c3628937056","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"În cadrul examenului gnatofotostatic, fotografia extraorală de profil servește la diagnosticarea disfuncțiilor stomatognatice. Care dintre următoarele elemente și repere anatomice corespund acestei examinări?","options":[{"id":"A","text":"Planul Dreyfus unește spina nazală anterioară cu punctul gnation."},{"id":"B","text":"Planul Simon reprezintă perpendiculara pe planul de la Frankfurt în punctul suborbitar și trece prin canin, comisură, gnation."},{"id":"C","text":"Unghiul dintre filtrul buzei superioare și cloazonul nazal are o valoare normală cuprinsă între 90 și 110°."},{"id":"D","text":"Perpendicularele din unghiurile interne ale ochilor servesc la aprecierea mărimii fantei labiale pe fotografia de profil."},{"id":"E","text":"Unghiul Hadjean este format de unghiul dintre tangentele la frunte și piramida nazală."}],"correct":["B","C","E"],"pages":[247],"source":"set-2"},{"id":"set2-HkopRC8U","fingerprint":"4e1685b10995e953","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Care dintre următoarele particularități sunt specifice examenului relațiilor fundamentale mandibulo-craniene?","options":[{"id":"A","text":"La pacientul edentat parțial întins, relația centrică are un caracter stabil datorită contactelor dento-dentare parțiale restante."},{"id":"B","text":"Examinarea spațiului de inocluzie fiziologică implică trasarea pe fața orală a incisivilor mandibulari a unei linii corespunzătoare marginii incizale a incisivilor superiori."},{"id":"C","text":"Relația centrică își menține caracterul normal dacă rapoartele ocluzale păstrează arcadele în afara triunghiului de toleranță ocluzală al lui Spirgi."},{"id":"D","text":"Spațiul de inocluzie fiziologică prezintă dimensiuni de 2 - 4 mm în zona frontală și 1,8 - 2,7 mm în zona laterală."},{"id":"E","text":"Depășirea triunghiului de toleranță ocluzală determină intercuspidarea maximă să stabilească rapoarte de malpoziție mandibulo-craniană prin rotație, translație și basculare."}],"correct":["D","E"],"pages":[244],"source":"set-2"},{"id":"set2-F6oG1cUq","fingerprint":"b826c3c3068682bf","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"În contextul edentației parțiale, care sunt metodele specifice de examinare paraclinică ale articulației temporo-mandibulare (ATM) și compartimentului muscular?","options":[{"id":"A","text":"Artroscopia cu fibră optică și cineradiografia se utilizează pentru investigarea paraclinică a articulației temporo-mandibulare."},{"id":"B","text":"Electromiografia (EMG) constituie o metodă de explorare paraclinică a compartimentului muscular."},{"id":"C","text":"Scintigrafia osoasă este listată ca o metodă de examinare paraclinică a compartimentului muscular."},{"id":"D","text":"Tonometria este destinată examenului obiectiv imagistic al articulației temporo-mandibulare."},{"id":"E","text":"Tomodensitometria reprezintă o investigație paraclinică indicată pentru compartimentul muscular."}],"correct":["A","B"],"pages":[246],"source":"set-2"},{"id":"set2-AuGp5lQn","fingerprint":"807e0cf518bc679d","chapterId":"set-2","subchapterId":"set2-3.03.2","type":"CM","text":"Evaluarea stării de igienă a cavității orale reprezintă baza profilaxiei gnatoprotetice. Pentru cuantificarea plăcii bacteriene prin intermediul revelatorilor de placă, se examinează anumite suprafețe dentare. Selectați afirmațiile corecte:","options":[{"id":"A","text":"Evaluarea depozitelor de tartru implică alte suprafețe dentare, complet distincte de cele analizate pentru placa bacteriană."},{"id":"B","text":"Se examinează fețele orale ale dinților 1.6, 1.2 și 2.1."},{"id":"C","text":"Se examinează fețele orale ale dinților 3.6, 3.2 și 4.1."},{"id":"D","text":"Se examinează fețele vestibulare ale dinților 3.6, 3.2 și 4.1."},{"id":"E","text":"Se examinează fețele vestibulare ale dinților 1.6, 1.2 și 2.1."}],"correct":["C","E"],"pages":[245],"source":"set-2"}];
